/* OWASP Top 10:2025 theory RU+EN — mapped to RØOT labs (labs unchanged) */
const THEORY_2025 = (() => {
  const DATA = {"intro": {"ru": "<h3>OWASP Top 10:2025 — теория по каждой категории</h3>\n<p class=\"theory-lead\">8-е издание, выпущено в ноябре 2025 (первое крупное обновление с 2021). Датасет: ~175k CVE, 589 CWE, данные по 2.8 млн приложений от Bugcrowd, Contrast Security, Semgrep, Veracode, Wallarm и др. Методология: 8 категорий формируются из статистики (incidence rate по CWE в протестированных приложениях + CVSS Exploit/Impact), 2 категории (A03 и A09) добавлены голосованием community survey, т.к. в тестовых данных их сложно обнаружить статистически.</p>\n<h3>Изменения относительно 2021</h3>\n<div class=\"rwrap\"><table class=\"rtab\"><thead><tr><th>2025</th><th>2021</th><th>Изменение</th></tr></thead><tbody><tr><td>A01 Broken Access Control</td><td>A01 Broken Access Control</td><td>Осталась #1, поглотила SSRF (было A10:2021)</td></tr><tr><td>A02 Security Misconfiguration</td><td>A05 Security Misconfiguration</td><td>Скачок #5 → #2</td></tr><tr><td>A03 Software Supply Chain Failures</td><td>A06 Vulnerable and Outdated Components</td><td>Расширена: не только известные CVE в компонентах, а весь supply chain (CI/CD, реестры пакетов, IDE)</td></tr><tr><td>A04 Cryptographic Failures</td><td>A02 Cryptographic Failures</td><td>Падение #2 → #4</td></tr><tr><td>A05 Injection</td><td>A03 Injection</td><td>Падение #3 → #5</td></tr><tr><td>A06 Insecure Design</td><td>A04 Insecure Design</td><td>Падение #4 → #6</td></tr><tr><td>A07 Authentication Failures</td><td>A07 Identification and Authentication Failures</td><td>Переименована, ранг тот же</td></tr><tr><td>A08 Software or Data Integrity Failures</td><td>A08 Software and Data Integrity Failures</td><td>Ранг тот же</td></tr><tr><td>A09 Security Logging &amp; Alerting Failures</td><td>A09 Security Logging and Monitoring Failures</td><td>Переименована (акцент на alerting, не просто логирование)</td></tr><tr><td>A10 Mishandling of Exceptional Conditions</td><td>— (новая)</td><td>Новая категория: error handling, fail-open, гонки состояний</td></tr></tbody></table></div>\n<p>SSRF (A10:2021) как отдельная категория исчезла — растворена в Broken Access Control, т.к. по сути SSRF — это нарушение контроля доступа на уровне сервера к внутренним ресурсам.</p>\n<hr class=\"theory-hr\">", "en": "<h3>OWASP Top 10:2025 — theory by category</h3>\n<p class=\"theory-lead\">8th edition, released November 2025 (first major update since 2021). Dataset: ~175k CVEs, 589 CWEs, data from 2.8 million applications (Bugcrowd, Contrast Security, Semgrep, Veracode, Wallarm, and others). Methodology: 8 categories from statistics (CWE incidence rates in tested apps + CVSS Exploit/Impact); 2 categories (A03 and A09) added by community survey vote because they are hard to detect statistically in test data.</p>\n<h3>Changes vs 2021</h3>\n<div class=\"rwrap\"><table class=\"rtab\"><thead><tr><th>2025</th><th>2021</th><th>Change</th></tr></thead><tbody><tr><td>A01 Broken Access Control</td><td>A01 Broken Access Control</td><td>Still #1; absorbed SSRF (was A10:2021)</td></tr><tr><td>A02 Security Misconfiguration</td><td>A05 Security Misconfiguration</td><td>Jump #5 → #2</td></tr><tr><td>A03 Software Supply Chain Failures</td><td>A06 Vulnerable and Outdated Components</td><td>Expanded: not only known CVEs in components, but the whole supply chain (CI/CD, package registries, IDEs)</td></tr><tr><td>A04 Cryptographic Failures</td><td>A02 Cryptographic Failures</td><td>Drop #2 → #4</td></tr><tr><td>A05 Injection</td><td>A03 Injection</td><td>Drop #3 → #5</td></tr><tr><td>A06 Insecure Design</td><td>A04 Insecure Design</td><td>Drop #4 → #6</td></tr><tr><td>A07 Authentication Failures</td><td>A07 Identification and Authentication Failures</td><td>Renamed; same rank</td></tr><tr><td>A08 Software or Data Integrity Failures</td><td>A08 Software and Data Integrity Failures</td><td>Same rank</td></tr><tr><td>A09 Security Logging &amp; Alerting Failures</td><td>A09 Security Logging and Monitoring Failures</td><td>Renamed (emphasis on alerting, not just logging)</td></tr><tr><td>A10 Mishandling of Exceptional Conditions</td><td>— (new)</td><td>New category: error handling, fail-open, race conditions</td></tr></tbody></table></div>\n<p>SSRF (A10:2021) is no longer a standalone category — it is folded into Broken Access Control, because SSRF is essentially access-control failure for server-side reachability of internal resources.</p>\n<hr class=\"theory-hr\">"}, "summary": {"ru": "<div class=\"rwrap\"><table class=\"rtab\"><thead><tr><th>#</th><th>Категория</th><th>CWE</th><th>Ключевая идея</th></tr></thead><tbody><tr><td>A01</td><td>Broken Access Control</td><td>40</td><td>Проверка прав нарушена или отсутствует; включает IDOR/BFLA/CSRF/SSRF/CORS</td></tr><tr><td>A02</td><td>Security Misconfiguration</td><td>16</td><td>Разрыв между безопасным кодом и безопасным деплоем</td></tr><tr><td>A03</td><td>Software Supply Chain Failures</td><td>6</td><td>Компрометация зависимостей, CI/CD, реестров пакетов</td></tr><tr><td>A04</td><td>Cryptographic Failures</td><td>32</td><td>Слабая/отсутствующая защита данных in transit/at rest</td></tr><tr><td>A05</td><td>Injection</td><td>38</td><td>Недоверенные данные интерпретируются как код/структура запроса</td></tr><tr><td>A06</td><td>Insecure Design</td><td>—</td><td>Архитектурный провал, не чинится патчем</td></tr><tr><td>A07</td><td>Authentication Failures</td><td>36</td><td>Слабое подтверждение личности, брутфорс, session mgmt</td></tr><tr><td>A08</td><td>Software or Data Integrity Failures</td><td>—</td><td>Нет верификации подписи/происхождения кода и данных</td></tr><tr><td>A09</td><td>Security Logging &amp; Alerting Failures</td><td>—</td><td>Инцидент не обнаруживается/не эскалируется вовремя</td></tr><tr><td>A10</td><td>Mishandling of Exceptional Conditions</td><td>24</td><td>Некорректная реакция системы на нештатные условия (новая)</td></tr></tbody></table></div>\n<p>Источник: <a href=\"https://owasp.org/Top10/2025/\" target=\"_blank\" rel=\"noopener\">owasp.org/Top10/2025</a></p>", "en": "<div class=\"rwrap\"><table class=\"rtab\"><thead><tr><th>#</th><th>Category</th><th>CWE</th><th>Core idea</th></tr></thead><tbody><tr><td>A01</td><td>Broken Access Control</td><td>40</td><td>Authorization missing/broken; includes IDOR/BFLA/CSRF/SSRF/CORS</td></tr><tr><td>A02</td><td>Security Misconfiguration</td><td>16</td><td>Gap between secure code and secure deployment</td></tr><tr><td>A03</td><td>Software Supply Chain Failures</td><td>6</td><td>Compromised deps, CI/CD, package registries</td></tr><tr><td>A04</td><td>Cryptographic Failures</td><td>32</td><td>Weak/missing protection for data in transit/at rest</td></tr><tr><td>A05</td><td>Injection</td><td>38</td><td>Untrusted data interpreted as code/query structure</td></tr><tr><td>A06</td><td>Insecure Design</td><td>—</td><td>Architectural failure; not fixable by a patch</td></tr><tr><td>A07</td><td>Authentication Failures</td><td>36</td><td>Weak identity proofing, brute force, session mgmt</td></tr><tr><td>A08</td><td>Software or Data Integrity Failures</td><td>—</td><td>No signature/provenance verification</td></tr><tr><td>A09</td><td>Security Logging &amp; Alerting Failures</td><td>—</td><td>Incident not detected/escalated in time</td></tr><tr><td>A10</td><td>Mishandling of Exceptional Conditions</td><td>24</td><td>Incorrect reaction to abnormal conditions (new)</td></tr></tbody></table></div>\n<p>Source: <a href=\"https://owasp.org/Top10/2025/\" target=\"_blank\" rel=\"noopener\">owasp.org/Top10/2025</a></p>"}, "by2025": {"A01": {"ru": "<p>Access control — это принудительное применение политики: пользователь не должен иметь возможность действовать за пределами предоставленных ему разрешений. Модель контроля доступа обычно строится на трёх уровнях:</p>\n<ul><li><strong>Authentication</strong> — кто ты (не входит в эту категорию, см. A07);</li><li><strong>Authorization</strong> — что тебе разрешено;</li><li><strong>Enforcement</strong> — где и как это разрешение реально проверяется в коде.</li></ul>\n<p>Broken Access Control возникает, когда enforcement либо отсутствует, либо доверяет источникам, которые контролирует атакующий (клиентский код, параметры запроса, скрытые поля, JWT без должной проверки подписи/exp).</p>\n<p>Ключевой принцип: access control работает только тогда, когда проверка выполняется в доверенном серверном коде. Любая проверка, реализованная только на фронтенде (скрытие кнопки, disabled-поле, JS-роутинг) — не является контролем доступа, это UX.</p>\n<h3>Подкатегории (что относится сюда)</h3>\n<ol><li><strong>IDOR / BOLA (Insecure Direct Object Reference / Broken Object Level Authorization)</strong> — прямой доступ к объекту по идентификатору (<code class=\"inline\">/api/orders/1234</code>) без проверки, что объект принадлежит текущему пользователю.</li><li><strong>BFLA (Broken Function Level Authorization)</strong> — доступ к административной функции без проверки роли (<code class=\"inline\">POST /admin/users/delete</code>).</li><li><strong>Privilege Escalation</strong> — вертикальная (user → admin) и горизонтальная (user A → данные user B).</li><li><strong>Path Traversal</strong> (CWE-22/23/36) — выход за пределы разрешённой директории через <code class=\"inline\">../</code>.</li><li><strong>Force Browsing</strong> (CWE-425) — угадывание/перебор URL без ссылок в UI.</li><li><strong>CORS-мисконфигурация</strong> — <code class=\"inline\">Access-Control-Allow-Origin: *</code> вместе с <code class=\"inline\">Access-Control-Allow-Credentials: true</code>, или reflect-механизм Origin без валидации.</li><li><strong>CSRF</strong> (CWE-352) — принуждение авторизованного пользователя выполнить действие без его ведома (актуально там, где нет anti-CSRF токенов/SameSite).</li><li><strong>Metadata tampering</strong> — модификация JWT (алгоритм <code class=\"inline\">none</code>, подмена <code class=\"inline\">kid</code>, отсутствие проверки подписи), модификация hidden-полей/cookie для повышения прав.</li><li><strong>SSRF</strong> (CWE-918, включена сюда с 2025) — сервер по указке атакующего делает запрос к внутреннему/произвольному ресурсу (metadata endpoint облака, внутренние сервисы, localhost).</li><li><strong>Open Redirect</strong> (CWE-601) — используется как primitive для фишинга/обхода allow-list редиректов.</li><li><strong>Exposure of sensitive info</strong> (CWE-200/201) — раскрытие данных через отклик API, даже если само действие запрещено (напр., различие 403 vs 404 позволяет энумерацию).</li></ol>\n<h3>Как это тестируется (pentest-методология)</h3>\n<ul><li>Матрица ролей × эндпоинтов: для каждого privileged-эндпоинта проверять доступ от имени unauthenticated, low-priv, other-tenant пользователя.</li><li>IDOR-фаззинг: последовательный/предсказуемый инкремент ID, замена UUID на чужой (полученный в другой сессии).</li><li>Сравнение поведения UI и прямых запросов (curl/Burp) — то, что скрыто в UI, часто доступно через API.</li><li>Проверка методов: GET защищён, а PUT/DELETE/PATCH на том же ресурсе — нет.</li><li>JWT: <code class=\"inline\">alg=none</code>, подмена <code class=\"inline\">kid</code> на путь к файлу (JWK injection), брутфорс HMAC-секрета, отсутствие проверки <code class=\"inline\">aud</code>/<code class=\"inline\">iss</code>/<code class=\"inline\">exp</code>.</li><li>SSRF: инъекция localhost/127.0.0.1, <code class=\"inline\">169.254.169.254</code> (cloud metadata), DNS rebinding, обход allow-list через редиректы, IPv6/decimal/octal representation IP.</li><li>CORS: отправка произвольного <code class=\"inline\">Origin</code>, проверка, отражается ли он в <code class=\"inline\">Access-Control-Allow-Origin</code> вместе с <code class=\"inline\">Allow-Credentials: true</code>.</li></ul>\n<h3>Меры защиты</h3>\n<ul><li>Deny by default — доступ разрешён только явно.</li><li>Единая переиспользуемая точка проверки прав (не размазанная по контроллерам).</li><li>Проверка владения записью (record ownership) на уровне domain-модели, а не только на уровне маршрута.</li><li>Rate limiting на чувствительные эндпоинты.</li><li>Инвалидация серверных сессий при логауте; короткоживущие JWT + refresh-токены.</li><li>Логирование отказов авторизации и алертинг на повторяющиеся failures.</li></ul>\n<hr class=\"theory-hr\">", "en": "<p>Access control is policy enforcement: a user must not act outside permissions granted to them. Models usually have three layers:</p>\n<ul><li><strong>Authentication</strong> — who you are (not this category; see A07);</li><li><strong>Authorization</strong> — what you are allowed to do;</li><li><strong>Enforcement</strong> — where and how permission is actually checked in code.</li></ul>\n<p>Broken Access Control happens when enforcement is missing or trusts attacker-controlled inputs (client code, request parameters, hidden fields, JWTs without proper signature/exp checks).</p>\n<p>Key principle: access control only works when checks run in trusted server-side code. Any “check” only on the frontend (hiding a button, disabled fields, JS routing) is UX, not access control.</p>\n<h3>Subcategories (what belongs here)</h3>\n<ol><li><strong>IDOR / BOLA (Insecure Direct Object Reference / Broken Object Level Authorization)</strong> — direct access to an object by id (<code class=\"inline\">/api/orders/1234</code>) without verifying ownership.</li><li><strong>BFLA (Broken Function Level Authorization)</strong> — access to an admin function without a role check (<code class=\"inline\">POST /admin/users/delete</code>).</li><li><strong>Privilege Escalation</strong> — vertical (user → admin) and horizontal (user A → user B’s data).</li><li><strong>Path Traversal</strong> (CWE-22/23/36) — escaping the allowed directory via <code class=\"inline\">../</code>.</li><li><strong>Force Browsing</strong> (CWE-425) — guessing/enumerating URLs not linked in the UI.</li><li><strong>CORS misconfiguration</strong> — <code class=\"inline\">Access-Control-Allow-Origin: *</code> with <code class=\"inline\">Access-Control-Allow-Credentials: true</code>, or reflecting Origin without validation.</li><li><strong>CSRF</strong> (CWE-352) — forcing an authenticated user to perform an action without intent (where anti-CSRF tokens/SameSite are missing).</li><li><strong>Metadata tampering</strong> — JWT tricks (<code class=\"inline\">alg=none</code>, <code class=\"inline\">kid</code> swap, missing signature verification), hidden fields/cookies for privilege gain.</li><li><strong>SSRF</strong> (CWE-918, moved here in 2025) — server requests internal/arbitrary resources on the attacker’s behalf (cloud metadata, internal services, localhost).</li><li><strong>Open Redirect</strong> (CWE-601) — phishing / allow-list bypass primitive.</li><li><strong>Exposure of sensitive info</strong> (CWE-200/201) — data leak via API responses even when the action is “denied” (e.g. 403 vs 404 enables enumeration).</li></ol>\n<h3>How it is tested (pentest methodology)</h3>\n<ul><li>Role × endpoint matrix: every privileged endpoint as unauthenticated, low-priv, and other-tenant users.</li><li>IDOR fuzzing: sequential/predictable id increments, swapping UUIDs from another session.</li><li>Compare UI behavior vs direct requests (curl/Burp) — hidden UI often still hits open APIs.</li><li>Method checks: GET protected but PUT/DELETE/PATCH on the same resource not.</li><li>JWT: <code class=\"inline\">alg=none</code>, <code class=\"inline\">kid</code> path/JWK injection, HMAC secret brute, missing <code class=\"inline\">aud</code>/<code class=\"inline\">iss</code>/<code class=\"inline\">exp</code>.</li><li>SSRF: localhost/127.0.0.1, <code class=\"inline\">169.254.169.254</code>, DNS rebinding, redirect allow-list bypass, IPv6/decimal/octal IP forms.</li><li>CORS: arbitrary Origin — is it reflected with Allow-Credentials: true?</li></ul>\n<h3>Defenses</h3>\n<ul><li>Deny by default — allow only explicitly.</li><li>Single reusable authorization point (not copy-pasted across controllers).</li><li>Record ownership checks in the domain model, not only at the route layer.</li><li>Rate limiting on sensitive endpoints.</li><li>Server-side session invalidation on logout; short-lived JWT + refresh tokens.</li><li>Log authorization failures and alert on repeated failures.</li></ul>\n<hr class=\"theory-hr\">"}, "A02": {"ru": "<p>Это категория про разрыв между «безопасно написанным кодом» и «безопасно развёрнутой системой». Misconfiguration может возникнуть на любом уровне стека: ОС, веб-сервер, application server, база данных, framework, облачные сервисы (S3 buckets, IAM policies), контейнерные оркестраторы.</p>\n<p>Типичные проявления:</p>\n<ul><li>Включённые debug/verbose-режимы в production (стектрейсы, debug-эндпоинты типа Django <code class=\"inline\">DEBUG=True</code>, Spring Boot Actuator без аутентификации).</li><li>Дефолтные учётные записи/пароли, не изменённые после установки.</li><li>Ненужные фичи включены (лишние порты, сервисы, страницы, примеры приложений, ненужные HTTP-методы — TRACE/OPTIONS).</li><li>Отсутствие security headers (CSP, X-Content-Type-Options, X-Frame-Options, HSTS).</li><li>Излишне подробные сообщения об ошибках, раскрывающие stack trace/версии ПО.</li><li>Неправильно настроенные разрешения облачных ресурсов (публичный S3 bucket, чрезмерно широкий IAM).</li><li>Отсутствие security hardening на всех уровнях стека приложения — «out-of-the-box» конфигурация без изменений.</li><li>Несогласованность конфигураций между окружениями (staging vs prod).</li></ul>\n<h3>Как тестируется</h3>\n<ul><li>Проверка HTTP-методов (OPTIONS/TRACE/PUT/DELETE) на всех эндпоинтах.</li><li>Поиск дефолтных путей: <code class=\"inline\">/actuator</code>, <code class=\"inline\">/.env</code>, <code class=\"inline\">/swagger-ui</code>, <code class=\"inline\">/wp-admin</code>, <code class=\"inline\">/.git/</code>, <code class=\"inline\">/console</code>, cloud metadata.</li><li>Анализ HTTP-заголовков ответа на предмет отсутствующих security headers.</li><li>Форсирование ошибок (некорректный Content-Type, битый JSON) — смотрим, не течёт ли стектрейс/версия фреймворка.</li><li>Инвентаризация облачных ресурсов: публичные бакеты, security groups «0.0.0.0/0», default VPC.</li><li>Проверка версий по баннерам (Server, X-Powered-By) и сопоставление с известными CVE.</li></ul>\n<h3>Меры защиты</h3>\n<ul><li>Repeatable hardening process, автоматизированное развёртывание (IaC) с baseline-конфигурацией, применяемой одинаково ко всем окружениям.</li><li>Минимальная платформа: убрать неиспользуемые фичи, компоненты, документацию, примеры.</li><li>Регулярный review и обновление конфигураций как части патч-менеджмента (см. A03).</li><li>Сегментированная архитектура (containers/cloud groups/ACL) между компонентами.</li><li>Автоматизированный процесс проверки эффективности конфигураций во всех окружениях (CI-проверки, config-as-code с тестами).</li></ul>\n<hr class=\"theory-hr\">", "en": "<p>The gap between “securely written code” and a “securely deployed system.” Misconfiguration can appear at any stack layer: OS, web server, app server, database, framework, cloud services (S3, IAM), orchestrators.</p>\n<p>Typical manifestations:</p>\n<ul><li>Debug/verbose modes in production (stack traces, debug endpoints like Django <code class=\"inline\">DEBUG=True</code>, unauthenticated Spring Boot Actuator).</li><li>Default accounts/passwords never changed after install.</li><li>Unnecessary features enabled (extra ports, sample apps, TRACE/OPTIONS).</li><li>Missing security headers (CSP, X-Content-Type-Options, X-Frame-Options, HSTS).</li><li>Overly detailed error messages leaking stacks/versions.</li><li>Over-permissive cloud ACLs (public buckets, overly broad IAM).</li><li>No hardening — “out-of-the-box” defaults left as-is.</li><li>Config drift between environments (staging vs prod).</li></ul>\n<h3>How it is tested</h3>\n<ul><li>HTTP method checks (OPTIONS/TRACE/PUT/DELETE) on all endpoints.</li><li>Default paths: <code class=\"inline\">/actuator</code>, <code class=\"inline\">/.env</code>, <code class=\"inline\">/swagger-ui</code>, <code class=\"inline\">/wp-admin</code>, <code class=\"inline\">/.git/</code>, <code class=\"inline\">/console</code>, cloud metadata.</li><li>Response header review for missing security headers.</li><li>Force errors (bad Content-Type, broken JSON) — look for stack/version leaks.</li><li>Cloud inventory: public buckets, <code class=\"inline\">0.0.0.0/0</code> security groups, default VPC.</li><li>Banner versioning (Server, X-Powered-By) mapped to known CVEs.</li></ul>\n<h3>Defenses</h3>\n<ul><li>Repeatable hardening and automated deployment (IaC) with the same baseline in every environment.</li><li>Minimal platform: remove unused features, samples, docs.</li><li>Regular config review as part of patch management (see A03).</li><li>Segmented architecture (containers/cloud groups/ACLs) between components.</li><li>Automated config effectiveness checks in all environments (CI, config-as-code tests).</li></ul>\n<hr class=\"theory-hr\">"}, "A03": {"ru": "<p>Раньше (2021) категория ограничивалась «известными уязвимостями в компонентах» (по сути — устаревшие библиотеки с публичными CVE). В 2025 scope расширен до всего жизненного цикла supply chain: сборка, распространение, обновление ПО, включая <strong>неизвестные</strong> (не только CVE) компрометации через доверенные каналы.</p>\n<p>Компонент (библиотека, framework, образ контейнера, CI/CD раннер, IDE-плагин) в приложении почти всегда исполняется с теми же привилегиями, что и само приложение. Поэтому компрометация зависимости = компрометация приложения.</p>\n<p>Признаки уязвимости:</p>\n<ul><li>Не отслеживаются версии всех компонентов (прямых и транзитивных зависимостей), клиентских и серверных.</li><li>ПО устарело/не поддерживается вендором (включая ОС, БД, рантаймы).</li><li>Нет регулярного сканирования уязвимостей и подписки на security bulletins.</li><li>Нет change management для CI/CD, репозиториев кода, артефакторных хранилищ.</li><li>Компоненты берутся из недоверенных источников.</li><li>Нет разделения обязанностей (один человек может закоммитить код и сразу задеплоить в прод без ревью).</li><li>CI/CD имеет более слабую защиту, чем системы, которые он собирает и деплоит.</li></ul>\n<h3>Типовые сценарии атак</h3>\n<ol><li><strong>Компрометация доверенного вендора</strong> — классика: SolarWinds (2019), ~18 000 организаций скомпрометированы через легитимное обновление.</li><li><strong>Условно-срабатывающий backdoor</strong> — вредоносный код активируется только при определённых условиях (напр., взлом Bybit на $1.5 млрд в 2025 через supply-chain атаку на кошелёк, срабатывавшую только при использовании конкретного целевого кошелька).</li><li><strong>Самораспространяющийся worm в пакетном реестре</strong> — атака <code class=\"inline\">Shai-Hulud</code> (2025, npm): вредоносные версии популярных пакетов с post-install скриптом, который крал секреты и, если находил npm-токен жертвы, автоматически публиковал заражённые версии её собственных пакетов — червь распространялся сам, поразил 500+ версий пакетов.</li><li><strong>Известные уязвимости в компонентах</strong> — Struts2 RCE (CVE-2017-5638, Equifax breach), Log4Shell (CVE-2021-44228).</li></ol>\n<h3>Как тестируется</h3>\n<ul><li>Построение SBOM (Software Bill of Materials) и сверка с базами уязвимостей (OSV, NVD).</li><li>Анализ транзитивных зависимостей (не только <code class=\"inline\">package.json</code>, но и весь дерево).</li><li>Проверка целостности пайплайна: кто может мержить/деплоить без ревью, есть ли branch protection, подписаны ли артефакты.</li><li>Проверка происхождения (provenance) артефактов — собраны ли они воспроизводимо, подписаны ли (Sigstore/cosign, SLSA).</li><li>Аудит прав доступа в реестрах пакетов (npm/pypi токены), IDE-расширений.</li></ul>\n<h3>Меры защиты</h3>\n<ul><li>Централизованный SBOM + непрерывный composition analysis (OWASP Dependency-Track, Dependency-Check, retire.js).</li><li>Пакеты только из официальных источников, предпочтение подписанным.</li><li>Постепенный (staged/canary) rollout обновлений, а не одновременный на всю инфраструктуру.</li><li>Hardening репозиториев кода, воркстанций разработчиков, CI/CD (MFA, least privilege, tamper-evident logs, environment-scoped secrets).</li><li>Мониторинг неподдерживаемых библиотек, план миграции при их обнаружении.</li></ul>\n<hr class=\"theory-hr\">", "en": "<p>In 2021 the category was mostly “known vulnerable components” (outdated libraries with public CVEs). In 2025 scope covers the full software lifecycle: build, distribute, update — including <strong>unknown</strong> compromises through trusted channels, not only CVE IDs.</p>\n<p>A component (library, framework, container image, CI runner, IDE plugin) usually runs with the same privileges as the app. Compromising a dependency compromises the application.</p>\n<p>Vulnerability signs:</p>\n<ul><li>No inventory of all components (direct and transitive), client and server.</li><li>Unsupported/outdated software (OS, DB, runtimes included).</li><li>No regular vulnerability scanning / security bulletins.</li><li>No change management for CI/CD, code repos, artifact stores.</li><li>Components pulled from untrusted sources.</li><li>No separation of duties (one person can commit and deploy to prod without review).</li><li>CI/CD weaker than the systems it builds and deploys.</li></ul>\n<h3>Typical attack scenarios</h3>\n<ol><li><strong>Trusted vendor compromise</strong> — classic: SolarWinds (2019), ~18,000 organizations via a legitimate update.</li><li><strong>Conditionally triggered backdoor</strong> — malware activates only under specific conditions (e.g. high-value crypto-wallet supply-chain cases).</li><li><strong>Self-propagating registry worm</strong> — e.g. npm “Shai-Hulud”-style campaigns: post-install steals tokens and republishes infected package versions.</li><li><strong>Known component CVEs</strong> — Struts2 RCE (CVE-2017-5638, Equifax), Log4Shell (CVE-2021-44228).</li></ol>\n<h3>How it is tested</h3>\n<ul><li>Build an SBOM and match against OSV/NVD.</li><li>Analyze transitive trees (not only top-level manifests).</li><li>Pipeline integrity: who can merge/deploy without review, branch protection, signed artifacts.</li><li>Artifact provenance — reproducible builds, signatures (Sigstore/cosign, SLSA).</li><li>Audit package registry tokens and IDE extensions.</li></ul>\n<h3>Defenses</h3>\n<ul><li>Central SBOM + continuous composition analysis (Dependency-Track, Dependency-Check, retire.js, etc.).</li><li>Packages only from official sources; prefer signed artifacts.</li><li>Staged/canary rollouts instead of simultaneous fleet updates.</li><li>Harden repos, developer workstations, CI/CD (MFA, least privilege, tamper-evident logs, environment-scoped secrets).</li><li>Monitor unsupported libraries with a migration plan.</li></ul>\n<hr class=\"theory-hr\">"}, "A04": {"ru": "<p>Категория про защиту данных in transit и at rest — конфиденциальность и целостность через криптографию. Раньше называлась Sensitive Data Exposure (2017) — переименована в 2021, т.к. exposure это симптом, а cryptographic failure — root cause.</p>\n<p>Сначала нужно определить: какие данные требуют защиты (PII, credentials, финансовые, медицинские, business secrets) — согласно применимым законам (GDPR, PCI DSS, HIPAA и т.д.).</p>\n<p>Типичные провалы:</p>\n<ul><li>Передача данных в открытом виде (HTTP, SMTP, FTP вместо TLS).</li><li>Использование устаревших/слабых алгоритмов (MD5, SHA1 для паролей, DES/RC4, кастомная «своя» криптография).</li><li>Дефолтные или слабые криптографические ключи, отсутствие их ротации.</li><li>Отсутствие проверки сертификатов, игнорирование ошибок TLS-хендшейка.</li><li>Хранение паролей без соли или с быстрыми хешами (MD5/SHA-256 напрямую вместо bcrypt/scrypt/argon2/PBKDF2).</li><li>Использование initialization vectors (IV) предсказуемо/повторно (ECB mode, статичный IV в CBC).</li><li>Хранение чувствительных данных дольше необходимого, включая кэши/логи/backups.</li><li>Смешение шифрования и кодирования (Base64 воспринимается как «защита»).</li></ul>\n<h3>Как тестируется</h3>\n<ul><li>Анализ TLS-конфигурации (тестовый сканер типа testssl.sh): версии протокола, cipher suites, наличие HSTS, валидность сертификатов.</li><li>Поиск чувствительных данных в открытом виде: в URL (query string логируется), в localStorage/cookies без флагов Secure/HttpOnly.</li><li>Анализ используемых криптопримитивов в коде/бинарнике (hardcoded keys, weak algorithms).</li><li>Проверка хранения паролей (через утечку БД/дампа, если есть доступ) — формат хешей.</li><li>Проверка padding oracle / bit-flipping для CBC-режимов.</li></ul>\n<h3>Меры защиты</h3>\n<ul><li>Классификация данных, минимизация хранения того, что не нужно (data minimization/tokenization/truncation).</li><li>Шифрование всех чувствительных данных at rest и in transit современными проверенными алгоритмами и протоколами (TLS 1.2+/1.3, AES-GCM).</li><li>Отдельное управление ключами (KMS/HSM), ротация, разделение ключей и данных.</li><li>Пароли — только через устойчивые к брутфорсу функции с солью (Argon2id, bcrypt, scrypt).</li><li>Отключение кэширования для откликов с чувствительными данными.</li><li>Верификация всех сертификатов и цепочек доверия, отказ от собственных крипто-реализаций.</li></ul>\n<hr class=\"theory-hr\">", "en": "<p>Protecting data in transit and at rest — confidentiality and integrity via cryptography. Formerly Sensitive Data Exposure (2017); renamed in 2021 because exposure is a symptom and cryptographic failure is the root cause.</p>\n<p>First classify which data needs protection (PII, credentials, financial, health, business secrets) under applicable law (GDPR, PCI DSS, HIPAA, etc.).</p>\n<p>Typical failures:</p>\n<ul><li>Cleartext transport (HTTP, SMTP, FTP instead of TLS).</li><li>Weak/obsolete algorithms (MD5/SHA1 for passwords, DES/RC4, home-grown crypto).</li><li>Default/weak keys, no rotation.</li><li>No certificate validation; ignoring TLS handshake errors.</li><li>Passwords without salt or with fast hashes (raw MD5/SHA-256 instead of bcrypt/scrypt/argon2/PBKDF2).</li><li>Predictable/reused IVs (ECB, static IV in CBC).</li><li>Keeping sensitive data longer than needed (caches/logs/backups).</li><li>Confusing encoding with encryption (Base64 as “protection”).</li></ul>\n<h3>How it is tested</h3>\n<ul><li>TLS config (testssl.sh): protocol versions, ciphers, HSTS, cert validity.</li><li>Sensitive data in cleartext: URL query strings, localStorage/cookies without Secure/HttpOnly.</li><li>Crypto primitives in code/binaries (hardcoded keys, weak algorithms).</li><li>Password storage format (when dumps are in scope).</li><li>Padding oracle / bit-flipping for CBC modes.</li></ul>\n<h3>Defenses</h3>\n<ul><li>Data classification and minimization (tokenization/truncation).</li><li>Encrypt sensitive data at rest and in transit with modern algorithms (TLS 1.2+/1.3, AES-GCM).</li><li>Separate key management (KMS/HSM), rotation, keys separated from data.</li><li>Passwords only via slow salted KDFs (Argon2id, bcrypt, scrypt).</li><li>Disable caching of sensitive responses.</li><li>Verify trust chains; never invent your own crypto.</li></ul>\n<hr class=\"theory-hr\">"}, "A05": {"ru": "<p>Инъекция — это когда недоверенные данные передаются интерпретатору (SQL, ОС-шелл, LDAP, XPath, NoSQL, шаблонизатор, ORM) как часть команды/запроса, и интерпретатор не может отличить данные от кода/структуры запроса.</p>\n<p>Root cause — отсутствие разделения между control plane и data plane при построении запроса/команды: конкатенация строк вместо параметризации.</p>\n<h3>Подтипы</h3>\n<ul><li><strong>SQL Injection</strong> — классика, включая blind (boolean/time-based), UNION-based, error-based, second-order.</li><li><strong>NoSQL Injection</strong> — операторы MongoDB (<code class=\"inline\">$where</code>, <code class=\"inline\">$ne</code>) через JSON-параметры.</li><li><strong>OS Command Injection</strong> — передача пользовательского ввода в системный вызов (<code class=\"inline\">exec</code>, <code class=\"inline\">system</code>, обратные кавычки в shell).</li><li><strong>LDAP Injection</strong> — манипуляция LDAP-фильтром.</li><li><strong>XPath/XML Injection</strong>, включая XXE (хотя XXE частично относится к A08/A05 в зависимости от механизма).</li><li><strong>Cross-Site Scripting (XSS)</strong> — Reflected, Stored, DOM-based — инъекция в контекст исполнения браузера (HTML/JS/CSS/URL).</li><li><strong>Template Injection (SSTI)</strong> — инъекция в серверный шаблонизатор (Jinja2, Twig, FreeMarker) → зачастую RCE.</li><li><strong>Header/CRLF Injection</strong> — инъекция в HTTP-заголовки (response splitting).</li><li><strong>Command/Expression Language Injection</strong> — OGNL, SpEL (Spring, Struts).</li></ul>\n<h3>Как тестируется</h3>\n<ul><li>Фаззинг всех входных точек (параметры, заголовки, cookies, файлы, JSON/XML тела) спецсимволами: <code class=\"inline\">&#x27; &quot; ; -- &lt;script&gt; {{7*7}} $(whoami)</code>.</li><li>Дифференциальный анализ откликов (время ответа для time-based blind, разница в контенте для boolean-based).</li><li>Контекстно-зависимый XSS-тест (атрибут/тег/JS-строка/URL — разный payload для каждого контекста).</li><li>Для SSTI — проверка через математические выражения шаблонизатора (<code class=\"inline\">{{7<em>7}}</code>, <code class=\"inline\">${7</em>7}</code>) и идентификация движка по поведению.</li><li>Статический анализ на конкатенацию строк в запросах к БД/шеллу.</li></ul>\n<h3>Меры защиты</h3>\n<ul><li>Параметризованные запросы / prepared statements (никогда — конкатенация в запрос).</li><li>ORM с безопасным API вместо ручного построения запросов (но помнить, что ORM тоже можно заставить генерировать инъекцию при неаккуратном использовании).</li><li>Позитивная валидация ввода («server-side input validation», allow-list).</li><li>Контекстно-зависимое экранирование вывода (HTML-entity/JS-escape/URL-escape в зависимости от места вставки в DOM).</li><li>Content Security Policy как defense-in-depth от XSS.</li><li>Ограничение прав учётной записи БД по принципу наименьших привилегий (LIMIT — read-only там, где не нужна запись).</li></ul>\n<hr class=\"theory-hr\">", "en": "<p>Injection is when untrusted data is passed to an interpreter (SQL, OS shell, LDAP, XPath, NoSQL, template engine, ORM) as part of a command/query so the interpreter cannot separate data from code/structure.</p>\n<p>Root cause: missing separation of control plane and data plane when building queries — string concatenation instead of parameterization.</p>\n<h3>Subtypes</h3>\n<ul><li><strong>SQL Injection</strong> — classic, including blind (boolean/time), UNION, error-based, second-order.</li><li><strong>NoSQL Injection</strong> — MongoDB operators (<code class=\"inline\">$where</code>, <code class=\"inline\">$ne</code>) via JSON parameters.</li><li><strong>OS Command Injection</strong> — user input into <code class=\"inline\">exec</code>/<code class=\"inline\">system</code>/shell backticks.</li><li><strong>LDAP Injection</strong> — LDAP filter manipulation.</li><li><strong>XPath/XML Injection</strong>, including XXE (sometimes overlaps A08 depending on mechanism).</li><li><strong>Cross-Site Scripting (XSS)</strong> — Reflected, Stored, DOM-based.</li><li><strong>Template Injection (SSTI)</strong> — Jinja2/Twig/FreeMarker → often RCE.</li><li><strong>Header/CRLF Injection</strong> — response splitting.</li><li><strong>Expression Language Injection</strong> — OGNL, SpEL (Spring, Struts).</li></ul>\n<h3>How it is tested</h3>\n<ul><li>Fuzz all inputs (params, headers, cookies, files, JSON/XML) with <code class=\"inline\">&#x27; &quot; ; -- &lt;script&gt; {{7*7}} $(whoami)</code>.</li><li>Differential responses (timing for time-based blind; content deltas for boolean).</li><li>Context-aware XSS payloads (attribute/tag/JS string/URL).</li><li>SSTI probes (<code class=\"inline\">{{7<em>7}}</code>, <code class=\"inline\">${7</em>7}</code>) and engine fingerprinting.</li><li>Static analysis for string concat into DB/shell sinks.</li></ul>\n<h3>Defenses</h3>\n<ul><li>Parameterized queries / prepared statements (never string-build queries).</li><li>Safe ORM APIs (remember ORM can still inject if misused).</li><li>Positive server-side input validation (allow-lists).</li><li>Context-aware output encoding.</li><li>CSP as XSS defense-in-depth.</li><li>Least-privilege DB accounts.</li></ul>\n<hr class=\"theory-hr\">"}, "A06": {"ru": "<p>Это категория про <strong>отсутствующие или неэффективные архитектурные и дизайн-контроли</strong> — в отличие от Security Misconfiguration (плохо настроенный правильный контроль) или Injection (плохая реализация правильной идеи), Insecure Design — это когда дизайн сам по себе не предусматривает нужный контроль, даже при идеальной реализации.</p>\n<p>Пример разницы: если приложение не проверяет CAPTCHA/rate-limit при массовой покупке лимитированного товара (бизнес-логика позволяет боту скупить весь сток) — это провал дизайна, а не бага реализации.</p>\n<p>Ключевые концепции:</p>\n<ul><li><strong>Threat modeling</strong> должен выполняться на этапе проектирования, не после релиза.</li><li><strong>Secure design patterns</strong> и reference architecture, переиспользуемые между проектами.</li><li><strong>Business logic abuse</strong> — злоупотребление легитимным функционалом не по назначению (например, endless refund loop, race condition в накрутке баллов лояльности, обход лимитов через параллельные запросы).</li><li>Разделение trust boundary на уровне архитектуры (tier separation).</li><li>Insecure design нельзя исправить патчем — только пересмотром архитектуры.</li></ul>\n<h3>Как тестируется</h3>\n<ul><li>Формальный threat modeling (STRIDE, PASTA, attack trees) как этап пентеста, а не только техническое сканирование.</li><li>Тестирование бизнес-логики: гонки состояний (race conditions) при одновременных запросах (например, двойной вывод средств через параллельные запросы на списание).</li><li>Проверка лимитов бизнес-процессов (может ли пользователь обойти количественные ограничения — купоны, лимиты запросов, промокоды).</li><li>Abuse-case тестирование, а не только happy-path.</li></ul>\n<h3>Меры защиты</h3>\n<ul><li>Secure development lifecycle с threat modeling для критичных user story/фич на этапе дизайна.</li><li>Библиотека переиспользуемых secure design паттернов и защитных компонентов (auth, rate limiting как сервисы).</li><li>Unit- и integration-тесты, покрывающие ключевые атакующие сценарии (не только позитивные тест-кейсы).</li><li>Сегрегация tier-ов по уровню доверия и данных.</li><li>Ограничение потребления ресурсов на уровне пользователя/сервиса, транзакции и API (rate limiting как часть архитектуры, не заплатка).</li></ul>\n<hr class=\"theory-hr\">", "en": "<p>Missing or ineffective <strong>architectural and design controls</strong>. Unlike Security Misconfiguration (good control, bad config) or Injection (good idea, bad implementation), Insecure Design means the design itself never included the needed control — even perfect coding cannot save it.</p>\n<p>Example: no CAPTCHA/rate-limit on limited stock checkout so bots buy everything — design failure, not a coding typo.</p>\n<p>Key concepts:</p>\n<ul><li><strong>Threat modeling</strong> at design time, not post-release.</li><li>Reusable <strong>secure design patterns</strong> and reference architectures.</li><li><strong>Business logic abuse</strong> — legitimate features misused (refund loops, loyalty races, parallel limit bypass).</li><li>Trust boundary separation at architecture level.</li><li>Cannot be “patched” — requires redesign.</li></ul>\n<h3>How it is tested</h3>\n<ul><li>Formal threat modeling (STRIDE, PASTA, attack trees) as a pentest phase.</li><li>Business-logic races (double spend via parallel requests).</li><li>Process limits (coupons, quotas, promos).</li><li>Abuse-case testing, not only happy path.</li></ul>\n<h3>Defenses</h3>\n<ul><li>SDL with threat modeling for critical stories/features at design time.</li><li>Library of reusable secure components (auth, rate limiting as services).</li><li>Unit/integration tests covering attacker scenarios, not only positive cases.</li><li>Tier segregation by trust and data sensitivity.</li><li>Resource limits per user/service/API as architecture, not afterthought.</li></ul>\n<hr class=\"theory-hr\">"}, "A07": {"ru": "<p>Подтверждение личности пользователя (identity) может быть ослаблено из-за:</p>\n<ul><li>Разрешения брутфорс-атак и credential stuffing (нет rate limiting/lockout/CAPTCHA).</li><li>Разрешения слабых, дефолтных или широко известных паролей («Password1», «admin/admin»).</li><li>Слабых процессов восстановления пароля/секретных вопросов, предсказуемых токенов сброса.</li><li>Хранения паролей в открытом виде/слабо хешированными (пересечение с A04).</li><li>Отсутствия или слабой multi-factor authentication.</li><li>Раскрытия session ID в URL (<code class=\"inline\">;jsessionid=</code>), отсутствия ротации session ID после успешного логина (session fixation).</li><li>Некорректного тайм-аута/невалидации сессий, особенно на shared/public компьютерах.</li></ul>\n<h3>Как тестируется</h3>\n<ul><li>Проверка политики паролей, наличия rate limiting/lockout на login/forgot-password эндпоинтах.</li><li>User enumeration через разное поведение (сообщение об ошибке, время ответа) при существующем/несуществующем логине.</li><li>Session fixation: устанавливается ли session ID до логина, меняется ли после.</li><li>Проверка предсказуемости/энтропии токенов сброса пароля, session ID.</li><li>Проверка обхода MFA (race condition, отсутствие проверки MFA-статуса на бэкенде, downgrade-атаки).</li><li>OAuth/OIDC misconfig: открытый redirect_uri, отсутствие проверки state-параметра (CSRF в OAuth flow), PKCE отсутствует для public client.</li></ul>\n<h3>Меры защиты</h3>\n<ul><li>MFA для доступа к чувствительным функциям, где это возможно.</li><li>Не деплоить дефолтные учётки, требовать смену дефолтных паролей.</li><li>Реализация NIST 800-63b рекомендаций по паролям (длина важнее сложности, проверка по спискам скомпрометированных паролей).</li><li>Rate limiting и учёт неудачных попыток с прогрессивными задержками/lockout без раскрытия деталей причины отказа.</li><li>Server-side, безопасное управление сессией: случайный session ID высокой энтропии, инвалидация после логаута/по таймауту, ротация после привилегированных действий.</li></ul>\n<hr class=\"theory-hr\">", "en": "<p>Identity proofing weakens when:</p>\n<ul><li>Brute force / credential stuffing allowed (no rate limit/lockout/CAPTCHA).</li><li>Weak/default/well-known passwords (“Password1”, admin/admin).</li><li>Weak recovery / security questions / predictable reset tokens.</li><li>Passwords stored cleartext or weakly hashed (overlaps A04).</li><li>Missing or weak MFA.</li><li>Session ID in URL (<code class=\"inline\">;jsessionid=</code>), no session rotation after login (fixation).</li><li>Poor timeout/invalidation, especially on shared devices.</li></ul>\n<h3>How it is tested</h3>\n<ul><li>Password policy; rate limit/lockout on login and forgot-password.</li><li>User enumeration via error messages/timing.</li><li>Session fixation: is SID set pre-login; does it change after?</li><li>Entropy of reset tokens and SIDs.</li><li>MFA bypass (race, server not enforcing MFA state, downgrade).</li><li>OAuth/OIDC: open redirect_uri, missing state, missing PKCE for public clients.</li></ul>\n<h3>Defenses</h3>\n<ul><li>MFA for sensitive functions where feasible.</li><li>No default accounts; force password change.</li><li>NIST 800-63B password guidance (length over complexity theater; breached-password checks).</li><li>Rate limiting and progressive delays without verbose failure reasons.</li><li>Server-side sessions: high-entropy random SID, invalidate on logout/timeout, rotate after privilege changes.</li></ul>\n<hr class=\"theory-hr\">"}, "A08": {"ru": "<p>Категория про отсутствие проверки целостности при работе с кодом и данными, где приложение доверяет источнику/содержимому без криптографической верификации. Отличие от A03 (Supply Chain): A08 — это integrity failures на уровне конкретного артефакта/данных (ниже уровнем), тогда как A03 — про весь процесс сборки/поставки экосистемы.</p>\n<p>Ключевые сценарии:</p>\n<ul><li><strong>Insecure deserialization</strong> — десериализация недоверенных данных без валидации типа/структуры может привести к RCE (Java, PHP, Python pickle, .NET BinaryFormatter).</li><li><strong>Отсутствие проверки цифровой подписи/хеша</strong> при auto-update механизмах (плагины, обновления ПО подтягиваются с CDN без проверки подписи).</li><li><strong>CI/CD pipeline без должного контроля целостности</strong> — возможность внедрить неавторизованный код, который затем считается доверенным.</li><li>Использование недоверенных плагинов/библиотек/CDN без Subresource Integrity (SRI) для клиентского JS.</li></ul>\n<h3>Как тестируется</h3>\n<ul><li>Поиск точек десериализации (Java <code class=\"inline\">ObjectInputStream</code>, PHP <code class=\"inline\">unserialize()</code>, Python <code class=\"inline\">pickle.loads()</code>) и проверка возможности инъекции вредоносного объекта (gadget chains — ysoserial и аналоги).</li><li>Проверка загружаемых с внешних CDN скриптов на наличие SRI-хешей (<code class=\"inline\">integrity=</code>).</li><li>Анализ auto-update механизмов: проверяется ли подпись/хеш перед установкой обновления.</li><li>Ревью CI/CD на предмет неподписанных артефактов, возможности подмены на этапе между сборкой и деплоем.</li></ul>\n<h3>Меры защиты</h3>\n<ul><li>Использование цифровых подписей для верификации происхождения ПО/данных.</li><li>Проверка, что зависимости и файлы приходят из ожидаемых репозиториев через verified/signed channel.</li><li>SRI для сторонних скриптов, CSP для ограничения источников исполняемого кода.</li><li>Не использовать десериализацию недоверенных данных вообще, либо использовать безопасные форматы (JSON без исполняемого кода) с строгой схемой валидации; изоляция/sandbox для процессов десериализации, если избежать нельзя.</li><li>Обязательное code review перед мержем в pipeline, отсутствие возможности деплоя без прохождения проверок.</li></ul>\n<hr class=\"theory-hr\">", "en": "<p>Missing integrity checks when the app trusts sources/content without cryptographic verification. Vs A03 (Supply Chain): A08 is integrity of a specific artifact/data; A03 is the broader build/delivery ecosystem.</p>\n<p>Key scenarios:</p>\n<ul><li><strong>Insecure deserialization</strong> — untrusted objects → RCE (Java, PHP, pickle, .NET BinaryFormatter).</li><li><strong>No signature/hash verification</strong> on auto-update (plugins/CDN updates).</li><li><strong>CI/CD without integrity controls</strong> — unauthorized code becomes “trusted.”</li><li>Untrusted plugins/CDN JS without Subresource Integrity (SRI).</li></ul>\n<h3>How it is tested</h3>\n<ul><li>Deserialization sinks (<code class=\"inline\">ObjectInputStream</code>, <code class=\"inline\">unserialize()</code>, <code class=\"inline\">pickle.loads()</code>) and gadget chains (ysoserial-class tools).</li><li>CDN scripts for SRI (<code class=\"inline\">integrity=</code>).</li><li>Auto-update: is signature/hash verified before install?</li><li>CI/CD: unsigned artifacts; swap between build and deploy.</li></ul>\n<h3>Defenses</h3>\n<ul><li>Digital signatures for software/data origin.</li><li>Dependencies only from expected verified/signed channels.</li><li>SRI for third-party scripts; CSP for script sources.</li><li>Avoid deserializing untrusted data; prefer JSON + schema; sandbox if unavoidable.</li><li>Mandatory review before merge; no deploy without checks.</li></ul>\n<hr class=\"theory-hr\">"}, "A09": {"ru": "<p>Без достаточного логирования и мониторинга инциденты не могут быть обнаружены. Категория традиционно недопредставлена в автоматизированных тестовых данных (сложно тестировать «отсутствие лога» сканером) — поэтому попадает в Top10 через community survey, а не только через статистику.</p>\n<p>Признаки недостаточности:</p>\n<ul><li>Аудируемые события (логины, неудачные попытки логина, отказы доступа, серверные ошибки высокой значимости) не логируются.</li><li>Предупреждения и ошибки генерируют логи с недостаточным контекстом для forensics (нет user id, timestamp, IP, trace id).</li><li>Логи хранятся только локально, без централизации (SIEM), без защиты от подделки/удаления атакующим.</li><li>Отсутствует эффективный alerting/пороги для аномалий в реальном времени — обнаружение инцидента занимает недели/месяцы вместо часов.</li><li>Приложение не способно обнаружить, эскалировать или сигнализировать об активной атаке в реальном времени.</li></ul>\n<h3>Как тестируется</h3>\n<ul><li>Проверка, генерируются ли логи при неудачных попытках логина, отказах авторизации, вводе явно вредоносных payload&#x27;ов (SQLi/XSS попытки).</li><li>Проверка возможности внедрения log injection (CRLF в поля, попадающие в лог, для подделки записей).</li><li>Оценка полноты контекста в логах (можно ли по логам восстановить цепочку событий инцидента).</li><li>Проверка защиты логов от модификации/удаления с правами приложения (пишет ли компрометированный процесс в append-only/централизованное хранилище).</li></ul>\n<h3>Меры защиты</h3>\n<ul><li>Логирование всех событий, связанных с аутентификацией, контролем доступа, валидацией ввода на стороне сервера, с достаточным контекстом для forensics, но без записи чувствительных данных (пароли/токены) в открытом виде.</li><li>Централизация логов в SIEM с настроенным alerting и эскалацией.</li><li>Формат логов, устойчивый к log injection (структурированное логирование, экранирование).</li><li>Playbook и regular drills для incident response (см. NIST 800-61r2).</li><li>Мониторинг DAST-сканирования/пентестов — приложение должно генерировать заметные алерты во время активного тестирования (если алертов нет — сам этот факт сигнализирует о провале мониторинга).</li></ul>\n<hr class=\"theory-hr\">", "en": "<p>Without enough logging and monitoring, incidents cannot be found. Under-represented in automated test data (hard for scanners to prove “no log”) — enters Top 10 largely via community survey.</p>\n<p>Signs of failure:</p>\n<ul><li>Auditable events (logins, failed logins, access denials, high-severity server errors) not logged.</li><li>Logs lack forensic context (user id, timestamp, IP, trace id).</li><li>Logs only local, no SIEM, no protection against attacker tampering/deletion.</li><li>No effective real-time alerting — discovery takes weeks/months instead of hours.</li><li>App cannot detect, escalate, or signal an active attack in real time.</li></ul>\n<h3>How it is tested</h3>\n<ul><li>Do failed logins / authz denials / obvious SQLi-XSS attempts create logs?</li><li>Log injection (CRLF into log fields) to forge records.</li><li>Can you reconstruct an incident timeline from logs?</li><li>Can a compromised app process delete/modify its own logs?</li></ul>\n<h3>Defenses</h3>\n<ul><li>Log auth, access control, and server-side validation events with forensic context — never raw passwords/tokens.</li><li>Centralize to SIEM with alerting and escalation.</li><li>Structured logging resistant to injection.</li><li>Incident response playbooks and drills (NIST 800-61r2).</li><li>During DAST/pentest, expect noticeable alerts; silence is itself a finding.</li></ul>\n<hr class=\"theory-hr\">"}, "A10": {"ru": "<p>Ранее часть этих CWE относили к «poor code quality» — в OWASP посчитали формулировку слишком общей и выделили конкретный фокус: <strong>как система ведёт себя, когда происходит что-то нештатное</strong>.</p>\n<p>Три типа провала обработки нештатной ситуации:</p>\n<ol><li>Приложение <strong>не предотвращает</strong> возникновение нештатной ситуации (нет валидации входа, нет лимитов).</li><li>Приложение <strong>не обнаруживает</strong> её в момент возникновения (ошибка проглатывается — <code class=\"inline\">catch (Exception e) {}</code>).</li><li>Приложение <strong>реагирует некорректно</strong> уже после того, как ситуация произошла (fail open вместо fail closed, частичный откат транзакции).</li></ol>\n<p>Причины: отсутствующая/неполная валидация ввода, обработка ошибок «на верхнем уровне» вместо места непосредственного возникновения, неожиданные состояния окружения (память, привилегии, сеть), несогласованная обработка исключений в разных частях кодовой базы, необработанные исключения вообще.</p>\n<p>Может проявляться как: логические баги, переполнения, race conditions, мошеннические транзакции, проблемы с состоянием/ресурсами/таймингом/аутентификацией/авторизацией.</p>\n<h3>Ключевые CWE</h3>\n<ul><li>CWE-209/CWE-550 — сообщение об ошибке содержит чувствительную информацию (стектрейс, версии, внутренние пути) → используется атакующим как разведка для построения более точной атаки (напр., детализированной SQLi).</li><li>CWE-636 «Not Failing Securely (Failing Open)» — при ошибке система по умолчанию <strong>разрешает</strong> действие вместо того, чтобы <strong>запретить</strong> (например, при сбое проверки прав доступа система пропускает пользователя вместо блокировки).</li><li>CWE-703/754/755 — общая improper handling/check нештатных условий.</li><li>CWE-476 NULL Pointer Dereference — сбой из-за необработанного null → крэш/DoS, иногда — обход последующей логики.</li><li>CWE-234/235 — пропущенные/лишние параметры не обрабатываются корректно.</li><li>CWE-369 Divide By Zero — как класс необработанного арифметического исключения.</li></ul>\n<h3>Типовые сценарии атак</h3>\n<ol><li><strong>Resource exhaustion (DoS)</strong> — приложение ловит исключение при загрузке файла, но не освобождает ресурс после ошибки; повторные ошибки исчерпывают доступные ресурсы (file handles, соединения, память).</li><li><strong>Sensitive data exposure через ошибки БД</strong> — полный текст ошибки БД показывается пользователю; атакующий намеренно форсирует разные ошибки, чтобы собрать структуру запроса/схему для более точной SQL-инъекции.</li><li><strong>State corruption в многошаговой транзакции</strong> — атакующий обрывает сетевое соединение посреди транзакции (списание → зачисление → лог); если система не откатывает всю операцию при сбое (fail closed), возможен race condition, позволяющий отправить средства несколько раз или обнулить баланс некорректно.</li></ol>\n<h3>Как тестируется</h3>\n<ul><li>Форсирование ошибок нестандартным вводом (некорректный Content-Type, обрыв соединения посреди multipart-запроса, edge-case значения: <code class=\"inline\">null</code>, пустая строка, отрицательные числа, переполнение буфера, экстремально длинные строки).</li><li>Проверка сообщений об ошибках на утечку внутренней информации (стектрейсы, пути, версии библиотек, SQL-запросы).</li><li>Тестирование race conditions в многошаговых операциях (параллельная отправка одного и того же запроса — списание средств, применение промокода, лимитированная покупка).</li><li>Проверка поведения при недоступности зависимого сервиса (fail open vs fail closed) — что происходит с авторизацией, если сервис проверки прав недоступен?</li><li>Load/stress-тестирование на предмер resource exhaustion через накопление необработанных исключений.</li></ul>\n<h3>Меры защиты</h3>\n<ul><li>Обработка исключений в месте их возникновения (не «выше по стеку» общим catch-all), с полноценной обработкой (лог + алерт + понятная пользователю ошибка без внутренних деталей).</li><li><strong>Fail closed</strong>, а не fail open: при сбое многошаговой операции — полный откат.</li><li>Централизованная (единая для всего приложения) стратегия обработки ошибок/логирования/алертинга, а не разные подходы в разных модулях.</li><li>Rate limiting, resource quotas, throttling — превентивно, чтобы не допускать нештатные условия вообще.</li><li>Строгая input-валидация с санитизацией на входе.</li><li>Threat modeling и код-ревью конкретно на предмет обработки ошибок; stress/penetration-тестирование финальной системы.</li></ul>\n<hr class=\"theory-hr\">", "en": "<p>Some of these CWEs used to sit under vague “poor code quality.” OWASP narrowed the focus to <strong>how the system behaves when something abnormal happens</strong>.</p>\n<p>Three failure types:</p>\n<ol><li>App <strong>does not prevent</strong> the exceptional condition (no input validation, no limits).</li><li>App <strong>does not detect</strong> it when it happens (swallowed errors — <code class=\"inline\">catch (Exception e) {}</code>).</li><li>App <strong>reacts incorrectly</strong> after it happens (fail open instead of fail closed; partial transaction rollback).</li></ol>\n<p>Causes: incomplete validation, catch-all high in the stack, unexpected environment state (memory, privileges, network), inconsistent exception handling, unhandled exceptions.</p>\n<p>May appear as logic bugs, overflows, races, fraud, resource/timing/authz failures.</p>\n<h3>Key CWEs</h3>\n<ul><li>CWE-209/CWE-550 — error messages leak sensitive info (stacks, versions, paths) used for recon (e.g. precise SQLi).</li><li>CWE-636 “Not Failing Securely (Failing Open)” — on error the system <strong>allows</strong> instead of <strong>denies</strong> (e.g. authz service down → allow).</li><li>CWE-703/754/755 — improper check/handling of exceptional conditions.</li><li>CWE-476 NULL Pointer Dereference — crash/DoS or logic skip.</li><li>CWE-234/235 — missing/extra parameters mishandled.</li><li>CWE-369 Divide By Zero — unhandled arithmetic exceptions.</li></ul>\n<h3>Typical attack scenarios</h3>\n<ol><li><strong>Resource exhaustion (DoS)</strong> — exception on upload path does not free resources; repeated errors exhaust handles/connections/memory.</li><li><strong>Sensitive data exposure via DB errors</strong> — full DB error text shown; attacker forces varied errors to map schema for SQLi.</li><li><strong>State corruption in multi-step transactions</strong> — mid-transaction disconnect; without full rollback (fail closed), races enable double-spend or bad balances.</li></ol>\n<h3>How it is tested</h3>\n<ul><li>Force errors with bad Content-Type, mid-multipart disconnects, edge values (<code class=\"inline\">null</code>, empty, negatives, huge strings).</li><li>Check error messages for internal leaks (stacks, paths, library versions, SQL).</li><li>Race multi-step flows (parallel withdraw/coupon/limited purchase).</li><li>Dependency outage behavior (fail open vs fail closed) — what happens to authz if the authz service is down?</li><li>Load/stress for resource exhaustion via unhandled exceptions.</li></ul>\n<h3>Defenses</h3>\n<ul><li>Handle exceptions where they occur (not only a global catch-all): log + alert + safe user message.</li><li><strong>Fail closed</strong>, not fail open: multi-step ops fully roll back on failure.</li><li>One application-wide error/logging/alerting strategy.</li><li>Rate limiting, quotas, throttling to prevent abnormal conditions.</li><li>Strict input validation/sanitization on entry.</li><li>Threat model and review error handling; stress and penetration test the final system.</li></ul>\n<hr class=\"theory-hr\">"}}, "byLab": {"A01": {"ru": "<p>Access control — это принудительное применение политики: пользователь не должен иметь возможность действовать за пределами предоставленных ему разрешений. Модель контроля доступа обычно строится на трёх уровнях:</p>\n<ul><li><strong>Authentication</strong> — кто ты (не входит в эту категорию, см. A07);</li><li><strong>Authorization</strong> — что тебе разрешено;</li><li><strong>Enforcement</strong> — где и как это разрешение реально проверяется в коде.</li></ul>\n<p>Broken Access Control возникает, когда enforcement либо отсутствует, либо доверяет источникам, которые контролирует атакующий (клиентский код, параметры запроса, скрытые поля, JWT без должной проверки подписи/exp).</p>\n<p>Ключевой принцип: access control работает только тогда, когда проверка выполняется в доверенном серверном коде. Любая проверка, реализованная только на фронтенде (скрытие кнопки, disabled-поле, JS-роутинг) — не является контролем доступа, это UX.</p>\n<h3>Подкатегории (что относится сюда)</h3>\n<ol><li><strong>IDOR / BOLA (Insecure Direct Object Reference / Broken Object Level Authorization)</strong> — прямой доступ к объекту по идентификатору (<code class=\"inline\">/api/orders/1234</code>) без проверки, что объект принадлежит текущему пользователю.</li><li><strong>BFLA (Broken Function Level Authorization)</strong> — доступ к административной функции без проверки роли (<code class=\"inline\">POST /admin/users/delete</code>).</li><li><strong>Privilege Escalation</strong> — вертикальная (user → admin) и горизонтальная (user A → данные user B).</li><li><strong>Path Traversal</strong> (CWE-22/23/36) — выход за пределы разрешённой директории через <code class=\"inline\">../</code>.</li><li><strong>Force Browsing</strong> (CWE-425) — угадывание/перебор URL без ссылок в UI.</li><li><strong>CORS-мисконфигурация</strong> — <code class=\"inline\">Access-Control-Allow-Origin: *</code> вместе с <code class=\"inline\">Access-Control-Allow-Credentials: true</code>, или reflect-механизм Origin без валидации.</li><li><strong>CSRF</strong> (CWE-352) — принуждение авторизованного пользователя выполнить действие без его ведома (актуально там, где нет anti-CSRF токенов/SameSite).</li><li><strong>Metadata tampering</strong> — модификация JWT (алгоритм <code class=\"inline\">none</code>, подмена <code class=\"inline\">kid</code>, отсутствие проверки подписи), модификация hidden-полей/cookie для повышения прав.</li><li><strong>SSRF</strong> (CWE-918, включена сюда с 2025) — сервер по указке атакующего делает запрос к внутреннему/произвольному ресурсу (metadata endpoint облака, внутренние сервисы, localhost).</li><li><strong>Open Redirect</strong> (CWE-601) — используется как primitive для фишинга/обхода allow-list редиректов.</li><li><strong>Exposure of sensitive info</strong> (CWE-200/201) — раскрытие данных через отклик API, даже если само действие запрещено (напр., различие 403 vs 404 позволяет энумерацию).</li></ol>\n<h3>Как это тестируется (pentest-методология)</h3>\n<ul><li>Матрица ролей × эндпоинтов: для каждого privileged-эндпоинта проверять доступ от имени unauthenticated, low-priv, other-tenant пользователя.</li><li>IDOR-фаззинг: последовательный/предсказуемый инкремент ID, замена UUID на чужой (полученный в другой сессии).</li><li>Сравнение поведения UI и прямых запросов (curl/Burp) — то, что скрыто в UI, часто доступно через API.</li><li>Проверка методов: GET защищён, а PUT/DELETE/PATCH на том же ресурсе — нет.</li><li>JWT: <code class=\"inline\">alg=none</code>, подмена <code class=\"inline\">kid</code> на путь к файлу (JWK injection), брутфорс HMAC-секрета, отсутствие проверки <code class=\"inline\">aud</code>/<code class=\"inline\">iss</code>/<code class=\"inline\">exp</code>.</li><li>SSRF: инъекция localhost/127.0.0.1, <code class=\"inline\">169.254.169.254</code> (cloud metadata), DNS rebinding, обход allow-list через редиректы, IPv6/decimal/octal representation IP.</li><li>CORS: отправка произвольного <code class=\"inline\">Origin</code>, проверка, отражается ли он в <code class=\"inline\">Access-Control-Allow-Origin</code> вместе с <code class=\"inline\">Allow-Credentials: true</code>.</li></ul>\n<h3>Меры защиты</h3>\n<ul><li>Deny by default — доступ разрешён только явно.</li><li>Единая переиспользуемая точка проверки прав (не размазанная по контроллерам).</li><li>Проверка владения записью (record ownership) на уровне domain-модели, а не только на уровне маршрута.</li><li>Rate limiting на чувствительные эндпоинты.</li><li>Инвалидация серверных сессий при логауте; короткоживущие JWT + refresh-токены.</li><li>Логирование отказов авторизации и алертинг на повторяющиеся failures.</li></ul>\n<hr class=\"theory-hr\">", "en": "<p>Access control is policy enforcement: a user must not act outside permissions granted to them. Models usually have three layers:</p>\n<ul><li><strong>Authentication</strong> — who you are (not this category; see A07);</li><li><strong>Authorization</strong> — what you are allowed to do;</li><li><strong>Enforcement</strong> — where and how permission is actually checked in code.</li></ul>\n<p>Broken Access Control happens when enforcement is missing or trusts attacker-controlled inputs (client code, request parameters, hidden fields, JWTs without proper signature/exp checks).</p>\n<p>Key principle: access control only works when checks run in trusted server-side code. Any “check” only on the frontend (hiding a button, disabled fields, JS routing) is UX, not access control.</p>\n<h3>Subcategories (what belongs here)</h3>\n<ol><li><strong>IDOR / BOLA (Insecure Direct Object Reference / Broken Object Level Authorization)</strong> — direct access to an object by id (<code class=\"inline\">/api/orders/1234</code>) without verifying ownership.</li><li><strong>BFLA (Broken Function Level Authorization)</strong> — access to an admin function without a role check (<code class=\"inline\">POST /admin/users/delete</code>).</li><li><strong>Privilege Escalation</strong> — vertical (user → admin) and horizontal (user A → user B’s data).</li><li><strong>Path Traversal</strong> (CWE-22/23/36) — escaping the allowed directory via <code class=\"inline\">../</code>.</li><li><strong>Force Browsing</strong> (CWE-425) — guessing/enumerating URLs not linked in the UI.</li><li><strong>CORS misconfiguration</strong> — <code class=\"inline\">Access-Control-Allow-Origin: *</code> with <code class=\"inline\">Access-Control-Allow-Credentials: true</code>, or reflecting Origin without validation.</li><li><strong>CSRF</strong> (CWE-352) — forcing an authenticated user to perform an action without intent (where anti-CSRF tokens/SameSite are missing).</li><li><strong>Metadata tampering</strong> — JWT tricks (<code class=\"inline\">alg=none</code>, <code class=\"inline\">kid</code> swap, missing signature verification), hidden fields/cookies for privilege gain.</li><li><strong>SSRF</strong> (CWE-918, moved here in 2025) — server requests internal/arbitrary resources on the attacker’s behalf (cloud metadata, internal services, localhost).</li><li><strong>Open Redirect</strong> (CWE-601) — phishing / allow-list bypass primitive.</li><li><strong>Exposure of sensitive info</strong> (CWE-200/201) — data leak via API responses even when the action is “denied” (e.g. 403 vs 404 enables enumeration).</li></ol>\n<h3>How it is tested (pentest methodology)</h3>\n<ul><li>Role × endpoint matrix: every privileged endpoint as unauthenticated, low-priv, and other-tenant users.</li><li>IDOR fuzzing: sequential/predictable id increments, swapping UUIDs from another session.</li><li>Compare UI behavior vs direct requests (curl/Burp) — hidden UI often still hits open APIs.</li><li>Method checks: GET protected but PUT/DELETE/PATCH on the same resource not.</li><li>JWT: <code class=\"inline\">alg=none</code>, <code class=\"inline\">kid</code> path/JWK injection, HMAC secret brute, missing <code class=\"inline\">aud</code>/<code class=\"inline\">iss</code>/<code class=\"inline\">exp</code>.</li><li>SSRF: localhost/127.0.0.1, <code class=\"inline\">169.254.169.254</code>, DNS rebinding, redirect allow-list bypass, IPv6/decimal/octal IP forms.</li><li>CORS: arbitrary Origin — is it reflected with Allow-Credentials: true?</li></ul>\n<h3>Defenses</h3>\n<ul><li>Deny by default — allow only explicitly.</li><li>Single reusable authorization point (not copy-pasted across controllers).</li><li>Record ownership checks in the domain model, not only at the route layer.</li><li>Rate limiting on sensitive endpoints.</li><li>Server-side session invalidation on logout; short-lived JWT + refresh tokens.</li><li>Log authorization failures and alert on repeated failures.</li></ul>\n<hr class=\"theory-hr\">"}, "A02": {"ru": "<p>Категория про защиту данных in transit и at rest — конфиденциальность и целостность через криптографию. Раньше называлась Sensitive Data Exposure (2017) — переименована в 2021, т.к. exposure это симптом, а cryptographic failure — root cause.</p>\n<p>Сначала нужно определить: какие данные требуют защиты (PII, credentials, финансовые, медицинские, business secrets) — согласно применимым законам (GDPR, PCI DSS, HIPAA и т.д.).</p>\n<p>Типичные провалы:</p>\n<ul><li>Передача данных в открытом виде (HTTP, SMTP, FTP вместо TLS).</li><li>Использование устаревших/слабых алгоритмов (MD5, SHA1 для паролей, DES/RC4, кастомная «своя» криптография).</li><li>Дефолтные или слабые криптографические ключи, отсутствие их ротации.</li><li>Отсутствие проверки сертификатов, игнорирование ошибок TLS-хендшейка.</li><li>Хранение паролей без соли или с быстрыми хешами (MD5/SHA-256 напрямую вместо bcrypt/scrypt/argon2/PBKDF2).</li><li>Использование initialization vectors (IV) предсказуемо/повторно (ECB mode, статичный IV в CBC).</li><li>Хранение чувствительных данных дольше необходимого, включая кэши/логи/backups.</li><li>Смешение шифрования и кодирования (Base64 воспринимается как «защита»).</li></ul>\n<h3>Как тестируется</h3>\n<ul><li>Анализ TLS-конфигурации (тестовый сканер типа testssl.sh): версии протокола, cipher suites, наличие HSTS, валидность сертификатов.</li><li>Поиск чувствительных данных в открытом виде: в URL (query string логируется), в localStorage/cookies без флагов Secure/HttpOnly.</li><li>Анализ используемых криптопримитивов в коде/бинарнике (hardcoded keys, weak algorithms).</li><li>Проверка хранения паролей (через утечку БД/дампа, если есть доступ) — формат хешей.</li><li>Проверка padding oracle / bit-flipping для CBC-режимов.</li></ul>\n<h3>Меры защиты</h3>\n<ul><li>Классификация данных, минимизация хранения того, что не нужно (data minimization/tokenization/truncation).</li><li>Шифрование всех чувствительных данных at rest и in transit современными проверенными алгоритмами и протоколами (TLS 1.2+/1.3, AES-GCM).</li><li>Отдельное управление ключами (KMS/HSM), ротация, разделение ключей и данных.</li><li>Пароли — только через устойчивые к брутфорсу функции с солью (Argon2id, bcrypt, scrypt).</li><li>Отключение кэширования для откликов с чувствительными данными.</li><li>Верификация всех сертификатов и цепочек доверия, отказ от собственных крипто-реализаций.</li></ul>\n<hr class=\"theory-hr\">", "en": "<p>Protecting data in transit and at rest — confidentiality and integrity via cryptography. Formerly Sensitive Data Exposure (2017); renamed in 2021 because exposure is a symptom and cryptographic failure is the root cause.</p>\n<p>First classify which data needs protection (PII, credentials, financial, health, business secrets) under applicable law (GDPR, PCI DSS, HIPAA, etc.).</p>\n<p>Typical failures:</p>\n<ul><li>Cleartext transport (HTTP, SMTP, FTP instead of TLS).</li><li>Weak/obsolete algorithms (MD5/SHA1 for passwords, DES/RC4, home-grown crypto).</li><li>Default/weak keys, no rotation.</li><li>No certificate validation; ignoring TLS handshake errors.</li><li>Passwords without salt or with fast hashes (raw MD5/SHA-256 instead of bcrypt/scrypt/argon2/PBKDF2).</li><li>Predictable/reused IVs (ECB, static IV in CBC).</li><li>Keeping sensitive data longer than needed (caches/logs/backups).</li><li>Confusing encoding with encryption (Base64 as “protection”).</li></ul>\n<h3>How it is tested</h3>\n<ul><li>TLS config (testssl.sh): protocol versions, ciphers, HSTS, cert validity.</li><li>Sensitive data in cleartext: URL query strings, localStorage/cookies without Secure/HttpOnly.</li><li>Crypto primitives in code/binaries (hardcoded keys, weak algorithms).</li><li>Password storage format (when dumps are in scope).</li><li>Padding oracle / bit-flipping for CBC modes.</li></ul>\n<h3>Defenses</h3>\n<ul><li>Data classification and minimization (tokenization/truncation).</li><li>Encrypt sensitive data at rest and in transit with modern algorithms (TLS 1.2+/1.3, AES-GCM).</li><li>Separate key management (KMS/HSM), rotation, keys separated from data.</li><li>Passwords only via slow salted KDFs (Argon2id, bcrypt, scrypt).</li><li>Disable caching of sensitive responses.</li><li>Verify trust chains; never invent your own crypto.</li></ul>\n<hr class=\"theory-hr\">"}, "A03": {"ru": "<p>Инъекция — это когда недоверенные данные передаются интерпретатору (SQL, ОС-шелл, LDAP, XPath, NoSQL, шаблонизатор, ORM) как часть команды/запроса, и интерпретатор не может отличить данные от кода/структуры запроса.</p>\n<p>Root cause — отсутствие разделения между control plane и data plane при построении запроса/команды: конкатенация строк вместо параметризации.</p>\n<h3>Подтипы</h3>\n<ul><li><strong>SQL Injection</strong> — классика, включая blind (boolean/time-based), UNION-based, error-based, second-order.</li><li><strong>NoSQL Injection</strong> — операторы MongoDB (<code class=\"inline\">$where</code>, <code class=\"inline\">$ne</code>) через JSON-параметры.</li><li><strong>OS Command Injection</strong> — передача пользовательского ввода в системный вызов (<code class=\"inline\">exec</code>, <code class=\"inline\">system</code>, обратные кавычки в shell).</li><li><strong>LDAP Injection</strong> — манипуляция LDAP-фильтром.</li><li><strong>XPath/XML Injection</strong>, включая XXE (хотя XXE частично относится к A08/A05 в зависимости от механизма).</li><li><strong>Cross-Site Scripting (XSS)</strong> — Reflected, Stored, DOM-based — инъекция в контекст исполнения браузера (HTML/JS/CSS/URL).</li><li><strong>Template Injection (SSTI)</strong> — инъекция в серверный шаблонизатор (Jinja2, Twig, FreeMarker) → зачастую RCE.</li><li><strong>Header/CRLF Injection</strong> — инъекция в HTTP-заголовки (response splitting).</li><li><strong>Command/Expression Language Injection</strong> — OGNL, SpEL (Spring, Struts).</li></ul>\n<h3>Как тестируется</h3>\n<ul><li>Фаззинг всех входных точек (параметры, заголовки, cookies, файлы, JSON/XML тела) спецсимволами: <code class=\"inline\">&#x27; &quot; ; -- &lt;script&gt; {{7*7}} $(whoami)</code>.</li><li>Дифференциальный анализ откликов (время ответа для time-based blind, разница в контенте для boolean-based).</li><li>Контекстно-зависимый XSS-тест (атрибут/тег/JS-строка/URL — разный payload для каждого контекста).</li><li>Для SSTI — проверка через математические выражения шаблонизатора (<code class=\"inline\">{{7<em>7}}</code>, <code class=\"inline\">${7</em>7}</code>) и идентификация движка по поведению.</li><li>Статический анализ на конкатенацию строк в запросах к БД/шеллу.</li></ul>\n<h3>Меры защиты</h3>\n<ul><li>Параметризованные запросы / prepared statements (никогда — конкатенация в запрос).</li><li>ORM с безопасным API вместо ручного построения запросов (но помнить, что ORM тоже можно заставить генерировать инъекцию при неаккуратном использовании).</li><li>Позитивная валидация ввода («server-side input validation», allow-list).</li><li>Контекстно-зависимое экранирование вывода (HTML-entity/JS-escape/URL-escape в зависимости от места вставки в DOM).</li><li>Content Security Policy как defense-in-depth от XSS.</li><li>Ограничение прав учётной записи БД по принципу наименьших привилегий (LIMIT — read-only там, где не нужна запись).</li></ul>\n<hr class=\"theory-hr\">", "en": "<p>Injection is when untrusted data is passed to an interpreter (SQL, OS shell, LDAP, XPath, NoSQL, template engine, ORM) as part of a command/query so the interpreter cannot separate data from code/structure.</p>\n<p>Root cause: missing separation of control plane and data plane when building queries — string concatenation instead of parameterization.</p>\n<h3>Subtypes</h3>\n<ul><li><strong>SQL Injection</strong> — classic, including blind (boolean/time), UNION, error-based, second-order.</li><li><strong>NoSQL Injection</strong> — MongoDB operators (<code class=\"inline\">$where</code>, <code class=\"inline\">$ne</code>) via JSON parameters.</li><li><strong>OS Command Injection</strong> — user input into <code class=\"inline\">exec</code>/<code class=\"inline\">system</code>/shell backticks.</li><li><strong>LDAP Injection</strong> — LDAP filter manipulation.</li><li><strong>XPath/XML Injection</strong>, including XXE (sometimes overlaps A08 depending on mechanism).</li><li><strong>Cross-Site Scripting (XSS)</strong> — Reflected, Stored, DOM-based.</li><li><strong>Template Injection (SSTI)</strong> — Jinja2/Twig/FreeMarker → often RCE.</li><li><strong>Header/CRLF Injection</strong> — response splitting.</li><li><strong>Expression Language Injection</strong> — OGNL, SpEL (Spring, Struts).</li></ul>\n<h3>How it is tested</h3>\n<ul><li>Fuzz all inputs (params, headers, cookies, files, JSON/XML) with <code class=\"inline\">&#x27; &quot; ; -- &lt;script&gt; {{7*7}} $(whoami)</code>.</li><li>Differential responses (timing for time-based blind; content deltas for boolean).</li><li>Context-aware XSS payloads (attribute/tag/JS string/URL).</li><li>SSTI probes (<code class=\"inline\">{{7<em>7}}</code>, <code class=\"inline\">${7</em>7}</code>) and engine fingerprinting.</li><li>Static analysis for string concat into DB/shell sinks.</li></ul>\n<h3>Defenses</h3>\n<ul><li>Parameterized queries / prepared statements (never string-build queries).</li><li>Safe ORM APIs (remember ORM can still inject if misused).</li><li>Positive server-side input validation (allow-lists).</li><li>Context-aware output encoding.</li><li>CSP as XSS defense-in-depth.</li><li>Least-privilege DB accounts.</li></ul>\n<hr class=\"theory-hr\">"}, "A04": {"ru": "<p>Это категория про <strong>отсутствующие или неэффективные архитектурные и дизайн-контроли</strong> — в отличие от Security Misconfiguration (плохо настроенный правильный контроль) или Injection (плохая реализация правильной идеи), Insecure Design — это когда дизайн сам по себе не предусматривает нужный контроль, даже при идеальной реализации.</p>\n<p>Пример разницы: если приложение не проверяет CAPTCHA/rate-limit при массовой покупке лимитированного товара (бизнес-логика позволяет боту скупить весь сток) — это провал дизайна, а не бага реализации.</p>\n<p>Ключевые концепции:</p>\n<ul><li><strong>Threat modeling</strong> должен выполняться на этапе проектирования, не после релиза.</li><li><strong>Secure design patterns</strong> и reference architecture, переиспользуемые между проектами.</li><li><strong>Business logic abuse</strong> — злоупотребление легитимным функционалом не по назначению (например, endless refund loop, race condition в накрутке баллов лояльности, обход лимитов через параллельные запросы).</li><li>Разделение trust boundary на уровне архитектуры (tier separation).</li><li>Insecure design нельзя исправить патчем — только пересмотром архитектуры.</li></ul>\n<h3>Как тестируется</h3>\n<ul><li>Формальный threat modeling (STRIDE, PASTA, attack trees) как этап пентеста, а не только техническое сканирование.</li><li>Тестирование бизнес-логики: гонки состояний (race conditions) при одновременных запросах (например, двойной вывод средств через параллельные запросы на списание).</li><li>Проверка лимитов бизнес-процессов (может ли пользователь обойти количественные ограничения — купоны, лимиты запросов, промокоды).</li><li>Abuse-case тестирование, а не только happy-path.</li></ul>\n<h3>Меры защиты</h3>\n<ul><li>Secure development lifecycle с threat modeling для критичных user story/фич на этапе дизайна.</li><li>Библиотека переиспользуемых secure design паттернов и защитных компонентов (auth, rate limiting как сервисы).</li><li>Unit- и integration-тесты, покрывающие ключевые атакующие сценарии (не только позитивные тест-кейсы).</li><li>Сегрегация tier-ов по уровню доверия и данных.</li><li>Ограничение потребления ресурсов на уровне пользователя/сервиса, транзакции и API (rate limiting как часть архитектуры, не заплатка).</li></ul>\n<hr class=\"theory-hr\">", "en": "<p>Missing or ineffective <strong>architectural and design controls</strong>. Unlike Security Misconfiguration (good control, bad config) or Injection (good idea, bad implementation), Insecure Design means the design itself never included the needed control — even perfect coding cannot save it.</p>\n<p>Example: no CAPTCHA/rate-limit on limited stock checkout so bots buy everything — design failure, not a coding typo.</p>\n<p>Key concepts:</p>\n<ul><li><strong>Threat modeling</strong> at design time, not post-release.</li><li>Reusable <strong>secure design patterns</strong> and reference architectures.</li><li><strong>Business logic abuse</strong> — legitimate features misused (refund loops, loyalty races, parallel limit bypass).</li><li>Trust boundary separation at architecture level.</li><li>Cannot be “patched” — requires redesign.</li></ul>\n<h3>How it is tested</h3>\n<ul><li>Formal threat modeling (STRIDE, PASTA, attack trees) as a pentest phase.</li><li>Business-logic races (double spend via parallel requests).</li><li>Process limits (coupons, quotas, promos).</li><li>Abuse-case testing, not only happy path.</li></ul>\n<h3>Defenses</h3>\n<ul><li>SDL with threat modeling for critical stories/features at design time.</li><li>Library of reusable secure components (auth, rate limiting as services).</li><li>Unit/integration tests covering attacker scenarios, not only positive cases.</li><li>Tier segregation by trust and data sensitivity.</li><li>Resource limits per user/service/API as architecture, not afterthought.</li></ul>\n<hr class=\"theory-hr\">"}, "A05": {"ru": "<p>Это категория про разрыв между «безопасно написанным кодом» и «безопасно развёрнутой системой». Misconfiguration может возникнуть на любом уровне стека: ОС, веб-сервер, application server, база данных, framework, облачные сервисы (S3 buckets, IAM policies), контейнерные оркестраторы.</p>\n<p>Типичные проявления:</p>\n<ul><li>Включённые debug/verbose-режимы в production (стектрейсы, debug-эндпоинты типа Django <code class=\"inline\">DEBUG=True</code>, Spring Boot Actuator без аутентификации).</li><li>Дефолтные учётные записи/пароли, не изменённые после установки.</li><li>Ненужные фичи включены (лишние порты, сервисы, страницы, примеры приложений, ненужные HTTP-методы — TRACE/OPTIONS).</li><li>Отсутствие security headers (CSP, X-Content-Type-Options, X-Frame-Options, HSTS).</li><li>Излишне подробные сообщения об ошибках, раскрывающие stack trace/версии ПО.</li><li>Неправильно настроенные разрешения облачных ресурсов (публичный S3 bucket, чрезмерно широкий IAM).</li><li>Отсутствие security hardening на всех уровнях стека приложения — «out-of-the-box» конфигурация без изменений.</li><li>Несогласованность конфигураций между окружениями (staging vs prod).</li></ul>\n<h3>Как тестируется</h3>\n<ul><li>Проверка HTTP-методов (OPTIONS/TRACE/PUT/DELETE) на всех эндпоинтах.</li><li>Поиск дефолтных путей: <code class=\"inline\">/actuator</code>, <code class=\"inline\">/.env</code>, <code class=\"inline\">/swagger-ui</code>, <code class=\"inline\">/wp-admin</code>, <code class=\"inline\">/.git/</code>, <code class=\"inline\">/console</code>, cloud metadata.</li><li>Анализ HTTP-заголовков ответа на предмет отсутствующих security headers.</li><li>Форсирование ошибок (некорректный Content-Type, битый JSON) — смотрим, не течёт ли стектрейс/версия фреймворка.</li><li>Инвентаризация облачных ресурсов: публичные бакеты, security groups «0.0.0.0/0», default VPC.</li><li>Проверка версий по баннерам (Server, X-Powered-By) и сопоставление с известными CVE.</li></ul>\n<h3>Меры защиты</h3>\n<ul><li>Repeatable hardening process, автоматизированное развёртывание (IaC) с baseline-конфигурацией, применяемой одинаково ко всем окружениям.</li><li>Минимальная платформа: убрать неиспользуемые фичи, компоненты, документацию, примеры.</li><li>Регулярный review и обновление конфигураций как части патч-менеджмента (см. A03).</li><li>Сегментированная архитектура (containers/cloud groups/ACL) между компонентами.</li><li>Автоматизированный процесс проверки эффективности конфигураций во всех окружениях (CI-проверки, config-as-code с тестами).</li></ul>\n<hr class=\"theory-hr\">", "en": "<p>The gap between “securely written code” and a “securely deployed system.” Misconfiguration can appear at any stack layer: OS, web server, app server, database, framework, cloud services (S3, IAM), orchestrators.</p>\n<p>Typical manifestations:</p>\n<ul><li>Debug/verbose modes in production (stack traces, debug endpoints like Django <code class=\"inline\">DEBUG=True</code>, unauthenticated Spring Boot Actuator).</li><li>Default accounts/passwords never changed after install.</li><li>Unnecessary features enabled (extra ports, sample apps, TRACE/OPTIONS).</li><li>Missing security headers (CSP, X-Content-Type-Options, X-Frame-Options, HSTS).</li><li>Overly detailed error messages leaking stacks/versions.</li><li>Over-permissive cloud ACLs (public buckets, overly broad IAM).</li><li>No hardening — “out-of-the-box” defaults left as-is.</li><li>Config drift between environments (staging vs prod).</li></ul>\n<h3>How it is tested</h3>\n<ul><li>HTTP method checks (OPTIONS/TRACE/PUT/DELETE) on all endpoints.</li><li>Default paths: <code class=\"inline\">/actuator</code>, <code class=\"inline\">/.env</code>, <code class=\"inline\">/swagger-ui</code>, <code class=\"inline\">/wp-admin</code>, <code class=\"inline\">/.git/</code>, <code class=\"inline\">/console</code>, cloud metadata.</li><li>Response header review for missing security headers.</li><li>Force errors (bad Content-Type, broken JSON) — look for stack/version leaks.</li><li>Cloud inventory: public buckets, <code class=\"inline\">0.0.0.0/0</code> security groups, default VPC.</li><li>Banner versioning (Server, X-Powered-By) mapped to known CVEs.</li></ul>\n<h3>Defenses</h3>\n<ul><li>Repeatable hardening and automated deployment (IaC) with the same baseline in every environment.</li><li>Minimal platform: remove unused features, samples, docs.</li><li>Regular config review as part of patch management (see A03).</li><li>Segmented architecture (containers/cloud groups/ACLs) between components.</li><li>Automated config effectiveness checks in all environments (CI, config-as-code tests).</li></ul>\n<hr class=\"theory-hr\">"}, "A06": {"ru": "<p>Раньше (2021) категория ограничивалась «известными уязвимостями в компонентах» (по сути — устаревшие библиотеки с публичными CVE). В 2025 scope расширен до всего жизненного цикла supply chain: сборка, распространение, обновление ПО, включая <strong>неизвестные</strong> (не только CVE) компрометации через доверенные каналы.</p>\n<p>Компонент (библиотека, framework, образ контейнера, CI/CD раннер, IDE-плагин) в приложении почти всегда исполняется с теми же привилегиями, что и само приложение. Поэтому компрометация зависимости = компрометация приложения.</p>\n<p>Признаки уязвимости:</p>\n<ul><li>Не отслеживаются версии всех компонентов (прямых и транзитивных зависимостей), клиентских и серверных.</li><li>ПО устарело/не поддерживается вендором (включая ОС, БД, рантаймы).</li><li>Нет регулярного сканирования уязвимостей и подписки на security bulletins.</li><li>Нет change management для CI/CD, репозиториев кода, артефакторных хранилищ.</li><li>Компоненты берутся из недоверенных источников.</li><li>Нет разделения обязанностей (один человек может закоммитить код и сразу задеплоить в прод без ревью).</li><li>CI/CD имеет более слабую защиту, чем системы, которые он собирает и деплоит.</li></ul>\n<h3>Типовые сценарии атак</h3>\n<ol><li><strong>Компрометация доверенного вендора</strong> — классика: SolarWinds (2019), ~18 000 организаций скомпрометированы через легитимное обновление.</li><li><strong>Условно-срабатывающий backdoor</strong> — вредоносный код активируется только при определённых условиях (напр., взлом Bybit на $1.5 млрд в 2025 через supply-chain атаку на кошелёк, срабатывавшую только при использовании конкретного целевого кошелька).</li><li><strong>Самораспространяющийся worm в пакетном реестре</strong> — атака <code class=\"inline\">Shai-Hulud</code> (2025, npm): вредоносные версии популярных пакетов с post-install скриптом, который крал секреты и, если находил npm-токен жертвы, автоматически публиковал заражённые версии её собственных пакетов — червь распространялся сам, поразил 500+ версий пакетов.</li><li><strong>Известные уязвимости в компонентах</strong> — Struts2 RCE (CVE-2017-5638, Equifax breach), Log4Shell (CVE-2021-44228).</li></ol>\n<h3>Как тестируется</h3>\n<ul><li>Построение SBOM (Software Bill of Materials) и сверка с базами уязвимостей (OSV, NVD).</li><li>Анализ транзитивных зависимостей (не только <code class=\"inline\">package.json</code>, но и весь дерево).</li><li>Проверка целостности пайплайна: кто может мержить/деплоить без ревью, есть ли branch protection, подписаны ли артефакты.</li><li>Проверка происхождения (provenance) артефактов — собраны ли они воспроизводимо, подписаны ли (Sigstore/cosign, SLSA).</li><li>Аудит прав доступа в реестрах пакетов (npm/pypi токены), IDE-расширений.</li></ul>\n<h3>Меры защиты</h3>\n<ul><li>Централизованный SBOM + непрерывный composition analysis (OWASP Dependency-Track, Dependency-Check, retire.js).</li><li>Пакеты только из официальных источников, предпочтение подписанным.</li><li>Постепенный (staged/canary) rollout обновлений, а не одновременный на всю инфраструктуру.</li><li>Hardening репозиториев кода, воркстанций разработчиков, CI/CD (MFA, least privilege, tamper-evident logs, environment-scoped secrets).</li><li>Мониторинг неподдерживаемых библиотек, план миграции при их обнаружении.</li></ul>\n<hr class=\"theory-hr\">", "en": "<p>In 2021 the category was mostly “known vulnerable components” (outdated libraries with public CVEs). In 2025 scope covers the full software lifecycle: build, distribute, update — including <strong>unknown</strong> compromises through trusted channels, not only CVE IDs.</p>\n<p>A component (library, framework, container image, CI runner, IDE plugin) usually runs with the same privileges as the app. Compromising a dependency compromises the application.</p>\n<p>Vulnerability signs:</p>\n<ul><li>No inventory of all components (direct and transitive), client and server.</li><li>Unsupported/outdated software (OS, DB, runtimes included).</li><li>No regular vulnerability scanning / security bulletins.</li><li>No change management for CI/CD, code repos, artifact stores.</li><li>Components pulled from untrusted sources.</li><li>No separation of duties (one person can commit and deploy to prod without review).</li><li>CI/CD weaker than the systems it builds and deploys.</li></ul>\n<h3>Typical attack scenarios</h3>\n<ol><li><strong>Trusted vendor compromise</strong> — classic: SolarWinds (2019), ~18,000 organizations via a legitimate update.</li><li><strong>Conditionally triggered backdoor</strong> — malware activates only under specific conditions (e.g. high-value crypto-wallet supply-chain cases).</li><li><strong>Self-propagating registry worm</strong> — e.g. npm “Shai-Hulud”-style campaigns: post-install steals tokens and republishes infected package versions.</li><li><strong>Known component CVEs</strong> — Struts2 RCE (CVE-2017-5638, Equifax), Log4Shell (CVE-2021-44228).</li></ol>\n<h3>How it is tested</h3>\n<ul><li>Build an SBOM and match against OSV/NVD.</li><li>Analyze transitive trees (not only top-level manifests).</li><li>Pipeline integrity: who can merge/deploy without review, branch protection, signed artifacts.</li><li>Artifact provenance — reproducible builds, signatures (Sigstore/cosign, SLSA).</li><li>Audit package registry tokens and IDE extensions.</li></ul>\n<h3>Defenses</h3>\n<ul><li>Central SBOM + continuous composition analysis (Dependency-Track, Dependency-Check, retire.js, etc.).</li><li>Packages only from official sources; prefer signed artifacts.</li><li>Staged/canary rollouts instead of simultaneous fleet updates.</li><li>Harden repos, developer workstations, CI/CD (MFA, least privilege, tamper-evident logs, environment-scoped secrets).</li><li>Monitor unsupported libraries with a migration plan.</li></ul>\n<hr class=\"theory-hr\">"}, "A07": {"ru": "<p>Подтверждение личности пользователя (identity) может быть ослаблено из-за:</p>\n<ul><li>Разрешения брутфорс-атак и credential stuffing (нет rate limiting/lockout/CAPTCHA).</li><li>Разрешения слабых, дефолтных или широко известных паролей («Password1», «admin/admin»).</li><li>Слабых процессов восстановления пароля/секретных вопросов, предсказуемых токенов сброса.</li><li>Хранения паролей в открытом виде/слабо хешированными (пересечение с A04).</li><li>Отсутствия или слабой multi-factor authentication.</li><li>Раскрытия session ID в URL (<code class=\"inline\">;jsessionid=</code>), отсутствия ротации session ID после успешного логина (session fixation).</li><li>Некорректного тайм-аута/невалидации сессий, особенно на shared/public компьютерах.</li></ul>\n<h3>Как тестируется</h3>\n<ul><li>Проверка политики паролей, наличия rate limiting/lockout на login/forgot-password эндпоинтах.</li><li>User enumeration через разное поведение (сообщение об ошибке, время ответа) при существующем/несуществующем логине.</li><li>Session fixation: устанавливается ли session ID до логина, меняется ли после.</li><li>Проверка предсказуемости/энтропии токенов сброса пароля, session ID.</li><li>Проверка обхода MFA (race condition, отсутствие проверки MFA-статуса на бэкенде, downgrade-атаки).</li><li>OAuth/OIDC misconfig: открытый redirect_uri, отсутствие проверки state-параметра (CSRF в OAuth flow), PKCE отсутствует для public client.</li></ul>\n<h3>Меры защиты</h3>\n<ul><li>MFA для доступа к чувствительным функциям, где это возможно.</li><li>Не деплоить дефолтные учётки, требовать смену дефолтных паролей.</li><li>Реализация NIST 800-63b рекомендаций по паролям (длина важнее сложности, проверка по спискам скомпрометированных паролей).</li><li>Rate limiting и учёт неудачных попыток с прогрессивными задержками/lockout без раскрытия деталей причины отказа.</li><li>Server-side, безопасное управление сессией: случайный session ID высокой энтропии, инвалидация после логаута/по таймауту, ротация после привилегированных действий.</li></ul>\n<hr class=\"theory-hr\">", "en": "<p>Identity proofing weakens when:</p>\n<ul><li>Brute force / credential stuffing allowed (no rate limit/lockout/CAPTCHA).</li><li>Weak/default/well-known passwords (“Password1”, admin/admin).</li><li>Weak recovery / security questions / predictable reset tokens.</li><li>Passwords stored cleartext or weakly hashed (overlaps A04).</li><li>Missing or weak MFA.</li><li>Session ID in URL (<code class=\"inline\">;jsessionid=</code>), no session rotation after login (fixation).</li><li>Poor timeout/invalidation, especially on shared devices.</li></ul>\n<h3>How it is tested</h3>\n<ul><li>Password policy; rate limit/lockout on login and forgot-password.</li><li>User enumeration via error messages/timing.</li><li>Session fixation: is SID set pre-login; does it change after?</li><li>Entropy of reset tokens and SIDs.</li><li>MFA bypass (race, server not enforcing MFA state, downgrade).</li><li>OAuth/OIDC: open redirect_uri, missing state, missing PKCE for public clients.</li></ul>\n<h3>Defenses</h3>\n<ul><li>MFA for sensitive functions where feasible.</li><li>No default accounts; force password change.</li><li>NIST 800-63B password guidance (length over complexity theater; breached-password checks).</li><li>Rate limiting and progressive delays without verbose failure reasons.</li><li>Server-side sessions: high-entropy random SID, invalidate on logout/timeout, rotate after privilege changes.</li></ul>\n<hr class=\"theory-hr\">"}, "A08": {"ru": "<p>Категория про отсутствие проверки целостности при работе с кодом и данными, где приложение доверяет источнику/содержимому без криптографической верификации. Отличие от A03 (Supply Chain): A08 — это integrity failures на уровне конкретного артефакта/данных (ниже уровнем), тогда как A03 — про весь процесс сборки/поставки экосистемы.</p>\n<p>Ключевые сценарии:</p>\n<ul><li><strong>Insecure deserialization</strong> — десериализация недоверенных данных без валидации типа/структуры может привести к RCE (Java, PHP, Python pickle, .NET BinaryFormatter).</li><li><strong>Отсутствие проверки цифровой подписи/хеша</strong> при auto-update механизмах (плагины, обновления ПО подтягиваются с CDN без проверки подписи).</li><li><strong>CI/CD pipeline без должного контроля целостности</strong> — возможность внедрить неавторизованный код, который затем считается доверенным.</li><li>Использование недоверенных плагинов/библиотек/CDN без Subresource Integrity (SRI) для клиентского JS.</li></ul>\n<h3>Как тестируется</h3>\n<ul><li>Поиск точек десериализации (Java <code class=\"inline\">ObjectInputStream</code>, PHP <code class=\"inline\">unserialize()</code>, Python <code class=\"inline\">pickle.loads()</code>) и проверка возможности инъекции вредоносного объекта (gadget chains — ysoserial и аналоги).</li><li>Проверка загружаемых с внешних CDN скриптов на наличие SRI-хешей (<code class=\"inline\">integrity=</code>).</li><li>Анализ auto-update механизмов: проверяется ли подпись/хеш перед установкой обновления.</li><li>Ревью CI/CD на предмет неподписанных артефактов, возможности подмены на этапе между сборкой и деплоем.</li></ul>\n<h3>Меры защиты</h3>\n<ul><li>Использование цифровых подписей для верификации происхождения ПО/данных.</li><li>Проверка, что зависимости и файлы приходят из ожидаемых репозиториев через verified/signed channel.</li><li>SRI для сторонних скриптов, CSP для ограничения источников исполняемого кода.</li><li>Не использовать десериализацию недоверенных данных вообще, либо использовать безопасные форматы (JSON без исполняемого кода) с строгой схемой валидации; изоляция/sandbox для процессов десериализации, если избежать нельзя.</li><li>Обязательное code review перед мержем в pipeline, отсутствие возможности деплоя без прохождения проверок.</li></ul>\n<hr class=\"theory-hr\">", "en": "<p>Missing integrity checks when the app trusts sources/content without cryptographic verification. Vs A03 (Supply Chain): A08 is integrity of a specific artifact/data; A03 is the broader build/delivery ecosystem.</p>\n<p>Key scenarios:</p>\n<ul><li><strong>Insecure deserialization</strong> — untrusted objects → RCE (Java, PHP, pickle, .NET BinaryFormatter).</li><li><strong>No signature/hash verification</strong> on auto-update (plugins/CDN updates).</li><li><strong>CI/CD without integrity controls</strong> — unauthorized code becomes “trusted.”</li><li>Untrusted plugins/CDN JS without Subresource Integrity (SRI).</li></ul>\n<h3>How it is tested</h3>\n<ul><li>Deserialization sinks (<code class=\"inline\">ObjectInputStream</code>, <code class=\"inline\">unserialize()</code>, <code class=\"inline\">pickle.loads()</code>) and gadget chains (ysoserial-class tools).</li><li>CDN scripts for SRI (<code class=\"inline\">integrity=</code>).</li><li>Auto-update: is signature/hash verified before install?</li><li>CI/CD: unsigned artifacts; swap between build and deploy.</li></ul>\n<h3>Defenses</h3>\n<ul><li>Digital signatures for software/data origin.</li><li>Dependencies only from expected verified/signed channels.</li><li>SRI for third-party scripts; CSP for script sources.</li><li>Avoid deserializing untrusted data; prefer JSON + schema; sandbox if unavoidable.</li><li>Mandatory review before merge; no deploy without checks.</li></ul>\n<hr class=\"theory-hr\">"}, "A09": {"ru": "<p>Без достаточного логирования и мониторинга инциденты не могут быть обнаружены. Категория традиционно недопредставлена в автоматизированных тестовых данных (сложно тестировать «отсутствие лога» сканером) — поэтому попадает в Top10 через community survey, а не только через статистику.</p>\n<p>Признаки недостаточности:</p>\n<ul><li>Аудируемые события (логины, неудачные попытки логина, отказы доступа, серверные ошибки высокой значимости) не логируются.</li><li>Предупреждения и ошибки генерируют логи с недостаточным контекстом для forensics (нет user id, timestamp, IP, trace id).</li><li>Логи хранятся только локально, без централизации (SIEM), без защиты от подделки/удаления атакующим.</li><li>Отсутствует эффективный alerting/пороги для аномалий в реальном времени — обнаружение инцидента занимает недели/месяцы вместо часов.</li><li>Приложение не способно обнаружить, эскалировать или сигнализировать об активной атаке в реальном времени.</li></ul>\n<h3>Как тестируется</h3>\n<ul><li>Проверка, генерируются ли логи при неудачных попытках логина, отказах авторизации, вводе явно вредоносных payload&#x27;ов (SQLi/XSS попытки).</li><li>Проверка возможности внедрения log injection (CRLF в поля, попадающие в лог, для подделки записей).</li><li>Оценка полноты контекста в логах (можно ли по логам восстановить цепочку событий инцидента).</li><li>Проверка защиты логов от модификации/удаления с правами приложения (пишет ли компрометированный процесс в append-only/централизованное хранилище).</li></ul>\n<h3>Меры защиты</h3>\n<ul><li>Логирование всех событий, связанных с аутентификацией, контролем доступа, валидацией ввода на стороне сервера, с достаточным контекстом для forensics, но без записи чувствительных данных (пароли/токены) в открытом виде.</li><li>Централизация логов в SIEM с настроенным alerting и эскалацией.</li><li>Формат логов, устойчивый к log injection (структурированное логирование, экранирование).</li><li>Playbook и regular drills для incident response (см. NIST 800-61r2).</li><li>Мониторинг DAST-сканирования/пентестов — приложение должно генерировать заметные алерты во время активного тестирования (если алертов нет — сам этот факт сигнализирует о провале мониторинга).</li></ul>\n<hr class=\"theory-hr\">", "en": "<p>Without enough logging and monitoring, incidents cannot be found. Under-represented in automated test data (hard for scanners to prove “no log”) — enters Top 10 largely via community survey.</p>\n<p>Signs of failure:</p>\n<ul><li>Auditable events (logins, failed logins, access denials, high-severity server errors) not logged.</li><li>Logs lack forensic context (user id, timestamp, IP, trace id).</li><li>Logs only local, no SIEM, no protection against attacker tampering/deletion.</li><li>No effective real-time alerting — discovery takes weeks/months instead of hours.</li><li>App cannot detect, escalate, or signal an active attack in real time.</li></ul>\n<h3>How it is tested</h3>\n<ul><li>Do failed logins / authz denials / obvious SQLi-XSS attempts create logs?</li><li>Log injection (CRLF into log fields) to forge records.</li><li>Can you reconstruct an incident timeline from logs?</li><li>Can a compromised app process delete/modify its own logs?</li></ul>\n<h3>Defenses</h3>\n<ul><li>Log auth, access control, and server-side validation events with forensic context — never raw passwords/tokens.</li><li>Centralize to SIEM with alerting and escalation.</li><li>Structured logging resistant to injection.</li><li>Incident response playbooks and drills (NIST 800-61r2).</li><li>During DAST/pentest, expect noticeable alerts; silence is itself a finding.</li></ul>\n<hr class=\"theory-hr\">"}, "A10": {"ru": "<div class=\"ebox info\">В OWASP Top 10:2025 отдельная категория SSRF (A10:2021) снята и отнесена к <strong>A01 Broken Access Control</strong>. В лаборатории RØOT модуль A10 сохраняет практический SSRF + fail-open (A10:2025). Ниже — теория <strong>A10:2025 Mishandling of Exceptional Conditions</strong>.</div>\n<p>Ранее часть этих CWE относили к «poor code quality» — в OWASP посчитали формулировку слишком общей и выделили конкретный фокус: <strong>как система ведёт себя, когда происходит что-то нештатное</strong>.</p>\n<p>Три типа провала обработки нештатной ситуации:</p>\n<ol><li>Приложение <strong>не предотвращает</strong> возникновение нештатной ситуации (нет валидации входа, нет лимитов).</li><li>Приложение <strong>не обнаруживает</strong> её в момент возникновения (ошибка проглатывается — <code class=\"inline\">catch (Exception e) {}</code>).</li><li>Приложение <strong>реагирует некорректно</strong> уже после того, как ситуация произошла (fail open вместо fail closed, частичный откат транзакции).</li></ol>\n<p>Причины: отсутствующая/неполная валидация ввода, обработка ошибок «на верхнем уровне» вместо места непосредственного возникновения, неожиданные состояния окружения (память, привилегии, сеть), несогласованная обработка исключений в разных частях кодовой базы, необработанные исключения вообще.</p>\n<p>Может проявляться как: логические баги, переполнения, race conditions, мошеннические транзакции, проблемы с состоянием/ресурсами/таймингом/аутентификацией/авторизацией.</p>\n<h3>Ключевые CWE</h3>\n<ul><li>CWE-209/CWE-550 — сообщение об ошибке содержит чувствительную информацию (стектрейс, версии, внутренние пути) → используется атакующим как разведка для построения более точной атаки (напр., детализированной SQLi).</li><li>CWE-636 «Not Failing Securely (Failing Open)» — при ошибке система по умолчанию <strong>разрешает</strong> действие вместо того, чтобы <strong>запретить</strong> (например, при сбое проверки прав доступа система пропускает пользователя вместо блокировки).</li><li>CWE-703/754/755 — общая improper handling/check нештатных условий.</li><li>CWE-476 NULL Pointer Dereference — сбой из-за необработанного null → крэш/DoS, иногда — обход последующей логики.</li><li>CWE-234/235 — пропущенные/лишние параметры не обрабатываются корректно.</li><li>CWE-369 Divide By Zero — как класс необработанного арифметического исключения.</li></ul>\n<h3>Типовые сценарии атак</h3>\n<ol><li><strong>Resource exhaustion (DoS)</strong> — приложение ловит исключение при загрузке файла, но не освобождает ресурс после ошибки; повторные ошибки исчерпывают доступные ресурсы (file handles, соединения, память).</li><li><strong>Sensitive data exposure через ошибки БД</strong> — полный текст ошибки БД показывается пользователю; атакующий намеренно форсирует разные ошибки, чтобы собрать структуру запроса/схему для более точной SQL-инъекции.</li><li><strong>State corruption в многошаговой транзакции</strong> — атакующий обрывает сетевое соединение посреди транзакции (списание → зачисление → лог); если система не откатывает всю операцию при сбое (fail closed), возможен race condition, позволяющий отправить средства несколько раз или обнулить баланс некорректно.</li></ol>\n<h3>Как тестируется</h3>\n<ul><li>Форсирование ошибок нестандартным вводом (некорректный Content-Type, обрыв соединения посреди multipart-запроса, edge-case значения: <code class=\"inline\">null</code>, пустая строка, отрицательные числа, переполнение буфера, экстремально длинные строки).</li><li>Проверка сообщений об ошибках на утечку внутренней информации (стектрейсы, пути, версии библиотек, SQL-запросы).</li><li>Тестирование race conditions в многошаговых операциях (параллельная отправка одного и того же запроса — списание средств, применение промокода, лимитированная покупка).</li><li>Проверка поведения при недоступности зависимого сервиса (fail open vs fail closed) — что происходит с авторизацией, если сервис проверки прав недоступен?</li><li>Load/stress-тестирование на предмер resource exhaustion через накопление необработанных исключений.</li></ul>\n<h3>Меры защиты</h3>\n<ul><li>Обработка исключений в месте их возникновения (не «выше по стеку» общим catch-all), с полноценной обработкой (лог + алерт + понятная пользователю ошибка без внутренних деталей).</li><li><strong>Fail closed</strong>, а не fail open: при сбое многошаговой операции — полный откат.</li><li>Централизованная (единая для всего приложения) стратегия обработки ошибок/логирования/алертинга, а не разные подходы в разных модулях.</li><li>Rate limiting, resource quotas, throttling — превентивно, чтобы не допускать нештатные условия вообще.</li><li>Строгая input-валидация с санитизацией на входе.</li><li>Threat modeling и код-ревью конкретно на предмет обработки ошибок; stress/penetration-тестирование финальной системы.</li></ul>\n<hr class=\"theory-hr\">", "en": "<div class=\"ebox info\">In OWASP Top 10:2025, standalone SSRF (A10:2021) was removed and folded into <strong>A01 Broken Access Control</strong>. RØOT module A10 still practices SSRF + fail-open (A10:2025). Below is <strong>A10:2025 Mishandling of Exceptional Conditions</strong> theory.</div>\n<p>Some of these CWEs used to sit under vague “poor code quality.” OWASP narrowed the focus to <strong>how the system behaves when something abnormal happens</strong>.</p>\n<p>Three failure types:</p>\n<ol><li>App <strong>does not prevent</strong> the exceptional condition (no input validation, no limits).</li><li>App <strong>does not detect</strong> it when it happens (swallowed errors — <code class=\"inline\">catch (Exception e) {}</code>).</li><li>App <strong>reacts incorrectly</strong> after it happens (fail open instead of fail closed; partial transaction rollback).</li></ol>\n<p>Causes: incomplete validation, catch-all high in the stack, unexpected environment state (memory, privileges, network), inconsistent exception handling, unhandled exceptions.</p>\n<p>May appear as logic bugs, overflows, races, fraud, resource/timing/authz failures.</p>\n<h3>Key CWEs</h3>\n<ul><li>CWE-209/CWE-550 — error messages leak sensitive info (stacks, versions, paths) used for recon (e.g. precise SQLi).</li><li>CWE-636 “Not Failing Securely (Failing Open)” — on error the system <strong>allows</strong> instead of <strong>denies</strong> (e.g. authz service down → allow).</li><li>CWE-703/754/755 — improper check/handling of exceptional conditions.</li><li>CWE-476 NULL Pointer Dereference — crash/DoS or logic skip.</li><li>CWE-234/235 — missing/extra parameters mishandled.</li><li>CWE-369 Divide By Zero — unhandled arithmetic exceptions.</li></ul>\n<h3>Typical attack scenarios</h3>\n<ol><li><strong>Resource exhaustion (DoS)</strong> — exception on upload path does not free resources; repeated errors exhaust handles/connections/memory.</li><li><strong>Sensitive data exposure via DB errors</strong> — full DB error text shown; attacker forces varied errors to map schema for SQLi.</li><li><strong>State corruption in multi-step transactions</strong> — mid-transaction disconnect; without full rollback (fail closed), races enable double-spend or bad balances.</li></ol>\n<h3>How it is tested</h3>\n<ul><li>Force errors with bad Content-Type, mid-multipart disconnects, edge values (<code class=\"inline\">null</code>, empty, negatives, huge strings).</li><li>Check error messages for internal leaks (stacks, paths, library versions, SQL).</li><li>Race multi-step flows (parallel withdraw/coupon/limited purchase).</li><li>Dependency outage behavior (fail open vs fail closed) — what happens to authz if the authz service is down?</li><li>Load/stress for resource exhaustion via unhandled exceptions.</li></ul>\n<h3>Defenses</h3>\n<ul><li>Handle exceptions where they occur (not only a global catch-all): log + alert + safe user message.</li><li><strong>Fail closed</strong>, not fail open: multi-step ops fully roll back on failure.</li><li>One application-wide error/logging/alerting strategy.</li><li>Rate limiting, quotas, throttling to prevent abnormal conditions.</li><li>Strict input validation/sanitization on entry.</li><li>Threat model and review error handling; stress and penetration test the final system.</li></ul>\n<hr class=\"theory-hr\">"}}, "mapLabTo2025": {"A01": "A01", "A02": "A04", "A03": "A05", "A04": "A06", "A05": "A02", "A06": "A03", "A07": "A07", "A08": "A08", "A09": "A09", "A10": "A10"}};
  function pick(obj, lang) {
    if (!obj) return '';
    if (typeof obj === 'string') return obj;
    const l = lang || (typeof I18n !== 'undefined' ? I18n.lang() : 'ru');
    return obj[l] || obj.en || obj.ru || '';
  }
  function forLab(code, lang) {
    return pick(DATA.byLab[code], lang);
  }
  return {
    intro: DATA.intro,
    summary: DATA.summary,
    by2025: DATA.by2025,
    byLab: DATA.byLab,
    mapLabTo2025: DATA.mapLabTo2025,
    pick,
    forLab,
  };
})();
